// Entries for the monuments, the board pieces and the states that appear on the map.
// When someone clicks a monument, a piece or an empire patch, the text comes from here.
// Each key joins a prefix and an identifier:
//   lm:<id>    monuments from landmarks.js (LANDMARKS)
//   wp:<id>    world pieces in pieces.js (WORLD_PIECES)
//   civ:<name> peoples and states in pieces.js (WORLD_CIVS), with the exact name used there
//   st:<name>  empires and states from the thread maps (KEYFRAMES in history.js) and the eras (ERAS in eras.js)
// Each entry has txt (2 to 4 sentences: what it is, who made it, when, why it matters, what happened next)
// and, sometimes, ev: ids of events from EVENTS (history.js + world.js) linked to it.
// Numbers are approximate when sources differ; when historians disagree, the text says so.

/* ---------- monuments (landmarks.js) ---------- */
const LM = {
  'lm:giza': { txt: 'The three great pyramids of Giza are the tombs of the pharaohs Khufu, Khafre and Menkaure, built around 2600 to 2500 BC. The largest, Khufu’s, was the tallest building in the world for almost 4,000 years. The people who built them were not slaves: nearby, archaeologists found villages of workers paid in bread and beer and recruited in shifts. In the Middle Ages the white limestone casing was stripped to build Cairo, which is why the steps show today.', ev: ['pyramids'] },
  'lm:stonehenge': { txt: 'Stonehenge, on Salisbury Plain in England, was built in phases starting around 3000 BC. The great sandstone blocks were set up around 2500 BC, and the smaller bluestones came from Wales, more than 200 km away. The circle lines up with the sunrise at the summer solstice and the sunset at the winter solstice. Graeber and Wengrow point out that the builders seem to have given up growing cereals and gone back to gathering hazelnuts, meeting here and at Durrington Walls for great seasonal feasts. What exactly it was for is still debated.' },
  'lm:greatwall': { txt: 'After unifying China in 221 BC, the first emperor, Qin Shi Huang, had the rammed-earth walls that rival kingdoms had already built in the north joined together. Almost everything visited today, in brick and stone, is much later, from the Ming dynasty (14th to 17th centuries). Adding up all the sections from every period, they come to more than 20,000 km. The wall served to control the border with the steppe peoples, such as the Xiongnu and the Mongols, and also trade and the movement of the empire’s own population out. It cannot be seen from space with the naked eye.', ev: ['hansilkroad', 'mongols'] },
  'lm:parthenon': { txt: 'Temple of the goddess Athena on the Acropolis of Athens, built between 447 and 432 BC, in the time of Pericles, by the architects Ictinus and Callicrates, with sculptures directed by Phidias. Part of the money came from the treasury of the Delian League, the alliance Athens led. It became a church, then a mosque under the Ottomans. In 1687 a Venetian cannon shot set off the gunpowder stored inside and destroyed the centre of the building. Between 1801 and 1812 Lord Elgin took a large part of the sculptures to London, where they remain in the British Museum, and Greece asks for their return.', ev: ['athens'] },
  'lm:colosseum': { txt: 'The Flavian Amphitheatre in Rome was begun by the emperor Vespasian around AD 72 and opened by his son Titus in AD 80, with 100 days of games. It held perhaps 50,000 people, who watched gladiator fights, animal hunts and executions for free. It was paid for with the plunder of Jerusalem in AD 70. Gladiator fights ended in the 5th century and the hunts in the 6th. Later, earthquakes and its use as a quarry took away half of the outer ring.', ev: ['romanrepublic', 'fallofrome'] },
  'lm:teotihuacan': { txt: 'The Pyramid of the Sun, about 65 metres tall, was built around AD 200 in Teotihuacan, in the Valley of Mexico, a city that reached nearly 100,000 inhabitants. The names of the city and the pyramid were given centuries later by the Mexica; no one knows what the inhabitants called it. Graeber and Wengrow stress that after about AD 300 the city stopped building great pyramids and built good stone apartment compounds for almost the whole population. Around 550 the centre was burned, and it is still debated whether by an internal revolt or by invaders.', ev: ['teotihuacan'] },
  'lm:hagia': { txt: 'Hagia Sophia was built in Constantinople between 532 and 537 on the orders of the emperor Justinian, by the architects Anthemius of Tralles and Isidore of Miletus, after the Nika riot burned the earlier church. Its dome was the largest in the world for almost a thousand years, and it was the cathedral of the Byzantine Empire for more than nine centuries. In 1453 Sultan Mehmed II turned it into a mosque and added the minarets. Atatürk made it a museum in 1934; in 2020 the Turkish government made it a mosque again.', ev: ['constantinople1453'] },
  'lm:tikal': { txt: 'Tikal, in the forests of the Petén in Guatemala, was one of the largest Maya cities, inhabited from about 800 BC and at its height between AD 200 and 850. In AD 378 an envoy linked to Teotihuacan arrived in the city and a new dynasty took the throne. For centuries Tikal fought Calakmul for dominance; the tallest temple-pyramids date from the 8th century. Around 900 it was abandoned, like other cities of the southern lowlands. Drought, war and soil exhaustion are the most debated explanations.', ev: ['maya', 'teotihuacan'] },
  'lm:borobudur': { txt: 'Borobudur, in central Java, Indonesia, is the largest Buddhist monument in the world, built between about AD 780 and 830 under the Sailendra dynasty. It is a stone mountain on nine platforms, with more than 2,600 relief panels and 504 Buddha statues, which pilgrims walk past as they climb in a spiral. When the centre of Javanese power moved east in the 10th century, the temple was neglected and covered by volcanic ash and brush, although local people knew it was there. It was uncovered from 1814 on and restored with UNESCO between 1975 and 1982.' },
  'lm:chichen': { txt: 'Chichén Itzá, in the north of the Yucatán Peninsula, was the most powerful city in the region between about AD 900 and 1100. Its architecture mixes the Maya style with that of central Mexico, and historians debate whether this came from a Toltec invasion or from exchange and alliances. Colonial sources say the city was ruled by a council rather than a single king, but this reading is also debated. At the equinoxes the temple of Kukulcán, the main pyramid, casts a shadow shaped like a serpent. After 1200, Mayapán took the city’s place.', ev: ['maya'] },
  'lm:cahokia': { txt: 'Cahokia, near today’s St. Louis in the United States, was the largest city north of Mexico before 1492, with perhaps 10,000 to 20,000 inhabitants at its height, between 1050 and 1200. At its centre stands Monks Mound, an earth mound about 30 metres high, the largest earthwork in the Americas north of Mesoamerica. There are signs of a strong elite, including human sacrifices in tombs. By around 1350 the city was empty, and Graeber and Wengrow suggest that the peoples of the region deliberately rejected that kind of power.', ev: ['cahokia'] },
  'lm:toweroflondon': { txt: 'The White Tower, the core of the Tower of London, was begun around 1078 by William the Conqueror, the Duke of Normandy who took England in 1066, to keep watch over the city. Over the centuries it was a palace, fortress, arsenal, mint, royal zoo and prison; Anne Boleyn was beheaded there in 1536. The British Crown Jewels are still kept in it today.' },
  'lm:zimbabwe': { txt: 'Great Zimbabwe, in the southeast of today’s Zimbabwe, was built between about 1100 and 1450 by ancestors of the Shona people, with walls of fitted stone, laid without mortar, up to 11 metres high. Its wealth came from cattle and from gold, sold through the Swahili ports on the coast; Chinese porcelain and Indian Ocean glass beads have been found there. In the 15th century the city declined, and power passed to Mutapa and other kingdoms. The white settlers of Rhodesia claimed Africans could not have built it; archaeologists proved otherwise as early as 1905 and 1929, and the independent country took its name in 1980.', ev: ['zimbabwe'] },
  'lm:angkor': { txt: 'Angkor Wat was built in the first half of the 12th century by the Khmer king Suryavarman II, as a Hindu temple to Vishnu and probably as his tomb. It is the largest religious monument in the world, at the heart of Angkor, capital of an empire that depended on a huge network of canals and reservoirs. At the end of the 13th century it became a Buddhist temple. The capital was left after the sack by Ayutthaya in 1431, but monks never abandoned the temple, which is now on the flag of Cambodia.' },
  'lm:djenne': { txt: 'According to tradition, the first mosque of Djenné, in today’s Mali, was built in the 13th century, when the city’s king converted to Islam. Today’s building dates from 1907, raised under French colonial rule by the city’s guild of masons, and it is the largest mud building in the world. Every year the inhabitants hold a festival to recoat the walls with fresh mud before the rains. Nearby lies Djenné-Djeno, a city more than 2,000 years old with no clear sign of a palace or a king.', ev: ['mansamusa'] },
  'lm:moai': { txt: 'The roughly 900 moai of Rapa Nui (Easter Island) were carved from volcanic stone at the Rano Raraku quarry, mostly between 1250 and 1500, by Polynesian navigators who reached the island around 1200 (the date is debated). They represented ancestors and were moved upright, rocked with ropes, to platforms on the coast. The idea that the islanders ruined the island by cutting down all the trees is disputed: rats brought in the canoes ate the palm seeds, and the great fall in population came after European contact, with disease and the kidnapping of about 1,500 people by Peruvian slavers in 1862 and 1863. Chile annexed the island in 1888.', ev: ['polynesia'] },
  'lm:notredame': { txt: 'The cathedral of Notre-Dame de Paris was begun in 1163 and was nearly finished by around 1260, with the towers and flying buttresses that defined the Gothic style. In the French Revolution it became a "Temple of Reason", and in 1804 Napoleon was crowned emperor there. Victor Hugo’s 1831 novel helped save the ruined building, which was restored by Viollet-le-Duc, who gave it its spire. In April 2019 a fire destroyed the roof and the spire; the cathedral reopened in December 2024.', ev: ['france1789', 'napoleon'] },
  'lm:templomayor': { txt: 'The Templo Mayor was the central pyramid of Tenochtitlan, with two shrines at the top: one for Huitzilopochtli, god of war and the sun, and one for Tláloc, god of rain. The Mexica enlarged it seven times, covering each version with a new one, from the founding of the city, which tradition places in 1325. After the conquest of 1521 the Spanish tore it down and used the stones in the new city. In 1978 workers found the Coyolxauhqui stone, and excavations revealed the remains in the centre of Mexico City.', ev: ['tenochtitlan', 'cortes', 'tlaxcala'] },
  'lm:alhambra': { txt: 'The Alhambra, in Granada, is the palace and fortress of the Nasrid dynasty, the last Muslim kingdom of the Iberian Peninsula, built mostly in the 13th and 14th centuries; the Court of the Lions dates from the 1370s. In January 1492 Sultan Boabdil handed the city over to Isabella of Castile and Ferdinand of Aragon. That same year the monarchs expelled the Jews and, in a camp nearby, signed the contract for Columbus’s voyage. Charles V built a Renaissance palace inside the complex in the 16th century.', ev: ['columbus1492'] },
  'lm:forbiddencity': { txt: 'The Forbidden City, in Beijing, was built between 1406 and 1420 by the Yongle Emperor of the Ming dynasty, when he moved the capital from Nanjing to the north; the same emperor sent Zheng He’s fleets to the Indian Ocean. For almost 500 years it was the residence of 24 Ming and Qing emperors, and no one could enter without permission. The last emperor, Puyi, abdicated in 1912 and lived there until 1924. Since 1925 it has been the Palace Museum.', ev: ['zhenghe'] },
  'lm:machupicchu': { txt: 'Machu Picchu, on an Andean ridge above the Urubamba River, was built in the 15th century as a royal estate of the Inca emperor Pachacuti; recent dating shows it was already inhabited around 1420. It had temples, farming terraces and houses for a few hundred people, nobles and servants. It was left at about the time of the Spanish conquest, and the Spanish seem never to have reached it. Local peasants knew the place; the American Hiram Bingham made it famous in 1911.', ev: ['inca', 'pizarro'] },
  'lm:elmina': { txt: 'The Castle of São Jorge da Mina was built in 1482 by the Portuguese on the Gold Coast, today’s Ghana, with stones brought from Portugal, to buy gold from the Akan peoples. It is the oldest European building south of the Sahara still standing. Over time it came to serve the trade in enslaved Africans, who were held in dungeons until they were shipped. The Dutch took it in 1637 and sold it to the British in 1872.', ev: ['slavetrade', 'dutch'] },
  'lm:kremlin': { txt: 'The Kremlin is the fortress at the centre of Moscow. Today’s red-brick walls and towers were built between 1485 and 1495 by Italian architects hired by Ivan III, the grand prince who stopped paying tribute to the Golden Horde in 1480. Inside are palaces and cathedrals where the tsars were crowned. Peter the Great moved the capital to Saint Petersburg in 1712, and the Bolsheviks brought it back in 1918. Since then it has been the seat of the Soviet government and, later, the Russian one.', ev: ['russianrev1917'] },
  'lm:belem': { txt: 'Belém Tower was built between 1514 and 1519, on the orders of King Manuel I, to defend the entrance to the port of Lisbon on the Tagus River, near the beach from which the fleets left for India and Brazil. The architect was Francisco de Arruda, and the decoration of ropes, armillary spheres and crosses of the Order of Christ is the style called Manueline. It later served as a prison, lighthouse and customs house.', ev: ['gama', 'cabral'] },
  'lm:jeronimos': { txt: 'The Jerónimos Monastery, in Belém, Lisbon, was begun by King Manuel I in 1501 or 1502, on the site of the chapel where Vasco da Gama prayed before leaving for India. The work was paid for largely by a tax on the pepper and spice trade and took almost a century. The monks of the Order of Saint Jerome stayed there until 1833, when religious orders were abolished in Portugal. It holds the tomb of Vasco da Gama and a tomb in honour of Camões.', ev: ['gama', 'cabral'] },
  'lm:reismagos': { txt: 'Reis Magos Fort, in Natal, was begun on 6 January 1598, Epiphany (the Day of the Kings), by the Portuguese, to drive out the French who traded brazilwood with the Potiguara on that coast. It is star-shaped, and the city of Natal grew up beside it the following year. The Dutch took it in 1633 and called it Castle Keulen, until they were driven out of Brazil in 1654.', ev: ['brazilwood', 'dutch'] },
  'lm:stpeters': { txt: 'St. Peter’s Basilica, in the Vatican, was built between 1506 and 1626 on the site of the old church of the emperor Constantine, over the tomb attributed to the apostle Peter. Bramante, Michelangelo (who designed the dome), Maderno and Bernini (who made the colonnaded square) all worked on it. To pay for the work, the Church sold indulgences, forgiveness of sins in exchange for money, and it was against this sale that Luther wrote his 95 Theses in 1517.', ev: ['luther1517'] },
  'lm:potala': { txt: 'The Potala Palace, in Lhasa, Tibet, was built from 1645 by the fifth Dalai Lama, who had united Tibet under his rule, on the site of a 7th-century palace. The White Palace was finished around 1648, and the Red Palace, with the tombs of the Dalai Lamas, in the 1690s. It was the winter residence and the seat of the Tibetan government until 1959, when the 14th Dalai Lama fled to India after a revolt against Chinese rule. Today it is a museum.', ev: ['china1949'] },
  'lm:taj': { txt: 'The Taj Mahal, in Agra, India, is the tomb the Mughal emperor Shah Jahan had built for his wife Mumtaz Mahal, who died in childbirth in 1631. The work, in white marble inlaid with stones, lasted from about 1632 to 1653 and employed thousands of craftsmen from across the empire. In 1658 Shah Jahan was deposed by his son Aurangzeb and spent the rest of his life confined in Agra Fort; he was buried beside her.' },
  'lm:versailles': { txt: 'Louis XIV turned his father’s hunting lodge into an immense palace and, in 1682, moved the court and the government of France there. Living at Versailles, under the king’s eye, was a way of binding the high nobility to a life of ceremonies and favours. In October 1789 a march of women from Paris forced Louis XVI to leave the palace. In the Hall of Mirrors the German Empire was proclaimed in 1871, and the peace treaty of 1919 was signed there after the First World War.', ev: ['france1789', 'ww1'] },
  'lm:aqueduct': { txt: 'The Carioca Aqueduct, today called the Arcos da Lapa, was finished in 1750 and carried water from the Carioca River, in the hills of Santa Teresa, to a fountain in the centre of Rio de Janeiro. It has 42 arches on two levels and is about 270 metres long, and it was built largely by enslaved workers. Rio was growing as the port for the gold of Minas Gerais and became the capital in 1763. Since 1896 the Santa Teresa tram has run across the top of the arches.', ev: ['gold', 'riocapital'] },
  'lm:saofrancisco': { txt: 'The Church of São Francisco de Assis in Ouro Preto was built from 1766 for the Third Order of Saint Francis, a brotherhood of the town’s rich laymen. The design and much of the sculpture are attributed to Antônio Francisco Lisboa, known as Aleijadinho, son of a Portuguese architect and an enslaved woman; the ceiling painting is by Manuel da Costa Ataíde. It is one of the best-known works of the Minas Gerais Baroque, paid for with gold mined by enslaved Africans. Ouro Preto was the first Brazilian city listed by UNESCO, in 1980.', ev: ['gold', 'minasconspiracy'] },
  'lm:geoglyphs': { txt: 'In eastern Acre and southern Amazonas there are more than 400 geometric ditches, in circles and squares up to 300 metres a side, dug between about 2,000 and 700 years ago. They came into view when the forest was cleared for pasture in the 1970s and 1980s. There are almost no remains of houses inside them, so they are seen as places for gatherings and ceremonies. They show that Amazonian peoples had long managed the forest without clearing it on a large scale.', ev: ['geoglyphs', 'terrapreta'] },
  'lm:marajo': { txt: 'Between about AD 400 and 1400, the people of the Marajoara culture built hundreds of mounds, the tesos, on Marajó Island in Pará, some more than 10 metres high, which kept them above the floods. They lived on them and buried their dead in painted pottery urns of very elaborate design. Whether it was a society of powerful chiefs or a more egalitarian one is still debated. The culture had already dispersed when the Europeans arrived.', ev: ['marajoara', 'terrapreta'] },
  'lm:teatroamazonas': { txt: 'The Teatro Amazonas, in Manaus, opened on 31 December 1896, at the height of the rubber boom, with marble, chandeliers and ironwork brought from Europe. The wealth came from latex gathered by rubber tappers, many of them migrants from the Northeast trapped in debt to their bosses, and by Indigenous people forced to work. After 1910, rubber from British plantations in Asia, grown from seeds taken out of the Amazon, brought prices crashing down, and Manaus fell into crisis.', ev: ['rubber'] },
  'lm:ipiranga': { txt: 'The Museu Paulista, or Ipiranga Museum, occupies a palace designed by the Italian Tommaso Bezzi and finished in 1890, beside the stream where Dom Pedro is said to have proclaimed independence on 7 September 1822. It was conceived as a monument to independence and opened as a museum in 1895, paid for by a São Paulo grown rich on coffee. It holds the painting Independence or Death by Pedro Américo, from 1888, which created the best-known image of the scene. Closed in 2013, it reopened for the bicentennial in 2022.', ev: ['independence', 'coffee'] },
  'lm:christ': { txt: 'Christ the Redeemer, at the top of Corcovado in Rio de Janeiro, was built between 1922 and 1931 and unveiled on 12 October 1931. It was designed by the engineer Heitor da Silva Costa, with the French sculptor Paul Landowski; the statue is reinforced concrete covered in small triangles of soapstone. The work was paid for with donations gathered by the Catholic Church, which was seeking more room in the secular Republic. It is 30 metres tall, plus 8 metres of pedestal.', ev: ['rev1930'] },
  'lm:congress': { txt: 'The National Congress in Brasília, designed by Oscar Niemeyer, opened with the city on 21 April 1960: two office towers, the upside-down dome of the Senate and the upturned bowl of the Chamber of Deputies. It was built by tens of thousands of migrant workers, the candangos. The dictatorship closed it more than once, the longest time after AI-5 (Institutional Act No. 5) in 1968. The 1988 Constitution was promulgated there.', ev: ['brasilia', 'coup64', 'diretas', 'constitution'] },
  'lm:eiffel': { txt: 'The Eiffel Tower was built between 1887 and 1889 by the company of the engineer Gustave Eiffel for the Paris Universal Exposition of 1889, which celebrated the centenary of the French Revolution. About 300 metres of iron, it was the tallest structure in the world until 1930. Many artists protested against it, and its permit called for demolition after 20 years; it was saved because it served as a radio antenna.', ev: ['france1789', 'industrialrev'] },
};

/* ---------- world pieces (pieces.js, WORLD_PIECES) ---------- */
const WP = {
  'wp:gobekli': { txt: 'Göbekli Tepe, in southeastern Turkey, has circles of stone pillars up to 5 metres tall carved with animals, raised around 9500 BC by people who still lived by hunting and gathering. It was read as a sanctuary for regional feasts; recent excavations have found houses and cisterns, and it is debated whether people lived there all year. The site shows that great monuments came before farming.', ev: ['gobeklitepe'] },
  'wp:wheat': { txt: 'In the Fertile Crescent, wheat and barley were domesticated gradually, between about 9500 and 6500 BC, alongside lentils, goats and sheep. Villages spent some 3,000 years planting a little, gathering and hunting, with no sudden "revolution". From these fields, cereal farming spread to Europe, Egypt and India.', ev: ['fertilewheat'] },
  'wp:jericho': { txt: 'Around 8000 BC the inhabitants of Jericho, an oasis near the Jordan River, built a stone wall and a tower about 8 metres high, among the oldest structures of this kind in the world. They grew wild and domesticated cereals and still hunted. What the wall was for is debated: defence against raids, protection from floods and mud, or a symbol of the community. It has nothing to do with the walls of the biblical story, which is much later.', ev: ['fertilewheat'] },
  'wp:catal': { txt: 'Çatalhöyük, on the Anatolian plateau, was inhabited between about 7400 and 6000 BC by thousands of people, in mud-brick houses packed against each other, with no streets and entrances through the roof. There is no palace or central temple, and men and women seem to have eaten the same food and done similar work. It is one of the most cited examples of urban life without visible rulers.', ev: ['catalhoyuk'] },
  'wp:maize': { txt: 'In the Balsas River valley, in southwestern Mexico, people began cultivating teosinte, a grass with tiny ears, about 9,000 years ago. It took millennia of selection to become maize with large ears, planted together with beans and squash. From Mexico, maize reached the Amazon and the Andes long before the Europeans, and after 1492 the whole world.', ev: ['balsasmaize'] },
  'wp:rice': { txt: 'In the Yangtze valley, in southern China, villages harvested wild rice more than 9,000 years ago, and domestication was slow: as late as about 4500 BC, rice shared the diet with acorns, chestnuts and fish. The flooded paddy fields that came later have fed much of East Asia’s population to this day.', ev: ['yangtzerice'] },
  'wp:uruk': { txt: 'Uruk, in southern Mesopotamia, had tens of thousands of inhabitants around 3300 BC. It is the source of the oldest clay tablets with writing, first used to count barley, beer, animals and temple workers. Writing was born as bookkeeping and only centuries later was used for poems and laws. Who ruled Uruk at this time is debated: a "priest-king", assemblies, or both.', ev: ['urukwriting'] },
  'wp:caral': { txt: 'Caral, in the Supe River valley in Peru, had stone pyramids and circular plazas around 2600 BC, at the same time as the pyramids of Egypt; it is the oldest known city in the Americas. It was part of a network of about 30 centres in the Norte Chico. There are almost no weapons or walls, and food came from fishing on the coast and from irrigated fields, traded between the valleys. It was abandoned around 1800 BC.', ev: ['caralnortechico'] },
  'wp:gutenberg': { txt: 'Around 1450, in Mainz, Germany, Johannes Gutenberg combined movable metal type, an oil-based ink and a press adapted from wine presses, and around 1455 he printed a Bible in about 180 copies. Movable type already existed in China and Korea, but in Europe, with an alphabet of few letters, the technique spread fast: by 1500 there were print shops in more than 200 cities. Gutenberg lost his workshop to the partner who had financed the work. Without the press, Luther’s Reformation would not have spread so quickly.', ev: ['gutenbergpress', 'luther1517'] },
  'wp:constantinople': { txt: 'On 29 May 1453, after almost two months of siege, the Ottoman sultan Mehmed II took Constantinople, capital of what was left of the Byzantine Empire. Giant cannons cast by a Hungarian engineer opened breaches in the walls that had held for a thousand years. The last emperor, Constantine XI, died in the fighting, and the city became the Ottoman capital, Istanbul.', ev: ['constantinople1453'] },
  'wp:columbus': { txt: 'On 12 October 1492, the three ships of Christopher Columbus, paid for by Queen Isabella of Castile, reached an island in the Bahamas that the Taíno called Guanahani. Columbus made four voyages and died believing he had come close to Asia. Within a few decades, violence, forced labour and epidemics nearly wiped out the Taíno of the Antilles, and the Spanish began bringing in enslaved Africans.', ev: ['columbus1492', 'tordesillas'] },
  'wp:luther': { txt: 'In 1517, in Wittenberg, the monk Martin Luther made public 95 theses against the Church’s sale of indulgences. Thanks to the printing press, his writings spread across Germany in weeks; he was excommunicated in 1521 and translated the Bible into German. In 1525 he condemned the peasants’ revolt, whose rebels had read in him a call to equality. The split between Catholics and Protestants led to more than a century of wars, until the Peace of Westphalia in 1648.', ev: ['luther1517', 'gutenbergpress', 'westphalia'] },
  'wp:magellan': { txt: 'Ferdinand Magellan, a Portuguese man in the service of Spain, left Seville in 1519 with five ships to reach the Spice Islands by sailing west. Between October and November 1520 he crossed the strait at the south of America that now bears his name. He died in 1521 in the Philippines, fighting the chief Lapulapu. In 1522 only one ship, commanded by Juan Sebastián Elcano, returned to Spain with 18 men, completing the first voyage around the world.', ev: ['tordesillas', 'manila'] },
  'wp:watt': { txt: 'In 1769, in Glasgow, James Watt patented a separate condenser that made the steam engine far more economical than Newcomen’s, which was used to pump water out of mines. In partnership with the industrialist Matthew Boulton in Birmingham from 1775, he adapted the engine to turn wheels and drive factories. Coal and steam lie at the heart of the British Industrial Revolution.', ev: ['industrialrev'] },
  'wp:railway': { txt: 'The Liverpool and Manchester Railway, opened on 15 September 1830, was the first to link two cities using only steam locomotives and fixed passenger timetables. The Rocket locomotive, by George and Robert Stephenson, won the competition to choose the line’s engine. The railway carried cotton from the port to the spinning mills; much of that cotton was picked by enslaved people in the southern United States. On opening day the MP William Huskisson was run over and killed.', ev: ['industrialrev'] },
  'wp:bigben': { txt: 'Big Ben is the name of the great bell in the clock tower of the Palace of Westminster, seat of the British Parliament, rebuilt after the fire of 1834 by the architects Charles Barry and Augustus Pugin. The clock started running in 1859, when Britain was the greatest industrial and colonial power in the world. In 2012 the tower was officially named the Elizabeth Tower.', ev: ['gloriousrev'] },
  'wp:suez': { txt: 'The Suez Canal, opened on 17 November 1869, links the Mediterranean to the Red Sea and greatly shortened the voyage from Europe to Asia. It was built by the company of the Frenchman Ferdinand de Lesseps with the forced labour of tens of thousands of Egyptian peasants; many died, and the number is debated. Deep in debt, Egypt sold its shares to the British in 1875 and was occupied by them in 1882. In 1956 President Nasser nationalised the canal, and France, Britain and Israel attacked it, without success.', ev: ['coldwar'] },
  'wp:transcont': { txt: 'The first transcontinental railroad in the United States was completed on 10 May 1869 at Promontory Summit, Utah, when the lines coming from California and from Omaha met. The western side was built mostly by thousands of Chinese immigrants, poorly paid and given the most dangerous jobs; the eastern side by Irish workers and Civil War veterans. The railroad sped up the settlement of the West, the slaughter of the bison and the expulsion of the Plains peoples.', ev: ['civilwar'] },
  'wp:liberty': { txt: 'The Statue of Liberty was a gift from France to the United States, sculpted by Frédéric Auguste Bartholdi, with an inner frame by Gustave Eiffel, and unveiled in New York on 28 October 1886. It celebrated American independence, and at its feet lie broken chains, a reminder of the end of slavery. Next to it, on Ellis Island, millions of immigrants passed through between 1892 and 1954, and the statue became a symbol of arrival.', ev: ['usa', 'civilwar', 'immigration'] },
  'wp:14bis': { txt: 'On 23 October 1906, at the Bagatelle field in Paris, the Brazilian Alberto Santos-Dumont flew about 60 metres in the 14-bis, before a committee of the Aéro-Club de France; in November he flew more than 200 metres. It was the first flight of an airplane that took off under its own power, publicly witnessed and certified. The Wright brothers had flown in the United States in 1903, with few witnesses, and the dispute over who flew first goes on, above all between Brazilians and Americans.' },
  'wp:panama': { txt: 'The Panama Canal, opened on 15 August 1914, links the Atlantic to the Pacific through a system of locks. A French attempt in the 1880s failed after about 20,000 deaths, mostly from yellow fever and malaria. The United States backed Panama’s separation from Colombia in 1903, took the canal zone and built the canal with workers who came largely from the Antilles. The canal passed to Panama on 31 December 1999.' },
  'wp:somme': { txt: 'The Battle of the Somme, in northern France, lasted from 1 July to 18 November 1916, between the British and French armies and the German army. On the first day alone the British army suffered about 57,000 casualties, nearly 20,000 of them dead, the worst day in its history. The first tanks appeared there in September. In the end the Allies advanced about 10 km, and the total dead and wounded on both sides passed 1 million.', ev: ['ww1'] },
  'wp:russianrev': { txt: 'In February 1917, strikes and mutinies in Petrograd brought down Tsar Nicholas II, and power was split between a provisional government and the soviets, councils of workers and soldiers. In October, Lenin’s Bolsheviks seized the Winter Palace and the government. A civil war followed from 1918 to 1921, and in 1922 the Soviet Union was born.', ev: ['russianrev1917'] },
  'wp:empire': { txt: 'The Empire State Building, in New York, went up in just over a year and opened on 1 May 1931, with 102 floors and 381 metres. It was the tallest building in the world until 1970. It was finished in the middle of the Great Depression, and so many offices stood empty that it was nicknamed the "Empty State Building".', ev: ['crash29'] },
  'wp:blitz': { txt: 'Between September 1940 and May 1941, the German air force bombed London and other British cities, almost every night for months. More than 40,000 civilians died, and many Londoners slept in Underground stations. The campaign did not force Britain to sue for peace.', ev: ['ww2'] },
  'wp:pearl': { txt: 'On 7 December 1941, Japanese Navy planes attacked the American naval base at Pearl Harbor, in Hawaii, and killed about 2,400 Americans. The next day the United States entered the Second World War. In 1942 the American government sent about 120,000 people of Japanese descent to camps, most of them American citizens.', ev: ['ww2'] },
  'wp:stalingrad': { txt: 'The Battle of Stalingrad, on the banks of the Volga, lasted from August 1942 to February 1943, with street-by-street fighting. In November the Red Army encircled the German 6th Army, which surrendered on 2 February 1943. It was one of the deadliest battles in history, with more than 1 million dead, wounded and captured on both sides combined, and it marked the turning point of the war on the Eastern Front.', ev: ['ww2'] },
  'wp:normandy': { txt: 'On 6 June 1944, D-Day, about 150,000 American, British, Canadian and other soldiers landed on five beaches in Normandy, in northern France. It was the largest amphibious operation in history and opened a new front against Germany in the west. Paris was liberated in August. At the same time, the Brazilian Expeditionary Force was arriving in Italy.', ev: ['ww2', 'feb'] },
  'wp:hiroshima': { txt: 'On 6 August 1945, the American bomber Enola Gay dropped on Hiroshima the first atomic bomb used in war. Tens of thousands of people died instantly, and about 140,000 by the end of the year, from the blast, the fire and the radiation. Whether the bombs were needed to end the war is still debated today.', ev: ['hiroshima1945', 'ww2'] },
  'wp:nagasaki': { txt: 'On 9 August 1945, three days after Hiroshima, a plutonium bomb was dropped on Nagasaki; the main target had been Kokura, covered by clouds that morning. About 70,000 people died by the end of the year. Japan announced its surrender on 15 August.', ev: ['hiroshima1945', 'ww2'] },
  'wp:sputnik': { txt: 'On 4 October 1957, the Soviet Union launched Sputnik 1, the first artificial satellite, from Baikonur in Kazakhstan: a 58 cm sphere that sent out radio beeps. The shock in the United States led to the creation of NASA in 1958 and to a space and missile race. In 1961 the Soviet Yuri Gagarin became the first man in space.', ev: ['coldwar'] },
  'wp:berlinwall': { txt: 'On the night of 13 August 1961, East Germany began building a wall around West Berlin to stop its citizens from fleeing to the West; millions had already left since 1949. At least 140 people died trying to cross it. On 9 November 1989, after months of protests, the government opened the crossings, and Berliners tore the wall down.', ev: ['coldwar', 'berlinwallfall'] },
  'wp:missiles': { txt: 'In October 1962, American spy planes photographed Soviet nuclear missile bases in Cuba. For 13 days Kennedy surrounded the island with ships, and the world came close to nuclear war. Khrushchev withdrew the missiles in exchange for an American promise not to invade Cuba and, secretly, the withdrawal of American missiles from Turkey.', ev: ['missiles1962', 'cuba1959', 'coldwar'] },
  'wp:vietnam': { txt: 'In 1965 the United States sent combat troops to South Vietnam to fight the guerrillas and Ho Chi Minh’s North Vietnam, and bombed the north of the country, Laos and Cambodia. At its peak it had more than 500,000 soldiers there; about 58,000 died, and more than 1 million Vietnamese were killed, with estimates going well beyond that. The war provoked huge protests in the United States and ended with the capture of Saigon by the North on 30 April 1975.', ev: ['coldwar'] },
  'wp:apollo': { txt: 'On 16 July 1969, a Saturn V rocket lifted off from Cape Canaveral, in Florida, carrying Neil Armstrong, Buzz Aldrin and Michael Collins. On 20 July Armstrong and Aldrin landed on the Sea of Tranquillity and walked on the Moon, while Collins stayed in orbit. The landing, watched live on television across much of the world, was the American victory in the space race against the Soviet Union.', ev: ['coldwar'] },
  'wp:opera': { txt: 'The Sydney Opera House, with its white shells above the harbour, was designed by the Dane Jørn Utzon, who won a competition in 1957. The work ran years late and cost more than ten times the estimate; Utzon resigned in 1966 and never saw it finished. It was opened by Queen Elizabeth II in 1973, on Bennelong Point, land of the Gadigal people.' },
  'wp:itaipu': { txt: 'The Itaipu dam, on the Paraná River, was agreed in 1973 between the dictatorships of Brazil and Paraguay and began producing power in 1984. For decades it was the world’s largest hydroelectric plant by output. Its lake drowned the Sete Quedas falls, one of the largest waterfalls in the world, and the lands of farmers and of Avá-Guarani communities.', ev: ['coup64'] },
  'wp:chernobyl': { txt: 'On 26 April 1986, reactor 4 of the Chernobyl power plant, in Soviet Ukraine, exploded during a safety test and spread radioactive material across Europe. About 30 people died in the first weeks; how many died later of cancer and other diseases is much debated, with estimates ranging from thousands to tens of thousands. More than 300,000 people were moved out of their homes. The government’s delay in admitting the disaster shook confidence in the Soviet regime.', ev: ['coldwar', 'berlinwallfall'] },
};

/* ---------- peoples and states of the world (pieces.js, WORLD_CIVS) ---------- */
const CIV = {
  'civ:Sumer': { txt: 'Sumer was the group of cities in southern Mesopotamia, such as Uruk, Ur, Lagash and Eridu, between about 3500 and 2000 BC. Cuneiform writing, ziggurats and some of the first laws and schools appeared there. The cities were independent and fought over water and land; texts mention assemblies of elders alongside kings. Around 2300 BC Sargon of Akkad conquered them, and after 2000 BC Sumerian stopped being spoken, but it lived on as a language of scholars for almost 2,000 years.', ev: ['urukwriting', 'hammurabi'] },
  'civ:Egypt': { txt: 'Pharaonic Egypt lasted from about 3100 BC, when the Nile valley and delta were unified, until 30 BC, when Cleopatra died and Rome annexed it. It had scribes, taxes paid in grain and a king seen as a god. Modern Egypt gained formal independence from Britain in 1922, but the British kept troops there and held the Suez Canal. In 1952 army officers overthrew the king; Nasser nationalised the canal in 1956 and became the leader of Arab nationalism, and Sadat made peace with Israel in 1979.', ev: ['pyramids', 'alexander'] },
  'civ:Indus Valley': { txt: 'The Indus, or Harappan, civilization covered an area larger than Egypt and Mesopotamia combined between about 2600 and 1900 BC, in today’s Pakistan and northwest India. Cities such as Harappa, Mohenjo-daro and Dholavira had planned streets, drains and standardised bricks, but no known palace or royal tomb. They traded with Mesopotamia, which called them Meluhha. The cities emptied after 1900 BC, perhaps because of changes in climate and rivers; the Indus script has still not been deciphered.', ev: ['mohenjodaro'] },
  'civ:Norte Chico (Caral)': { txt: 'Norte Chico is the name given to some 30 centres with pyramids and plazas in four valleys on Peru’s northern coast, between about 3000 and 1800 BC; Caral is the most studied. It is the oldest complex society in the Americas, contemporary with the pyramids of Egypt. People lived on anchovy fishing and on irrigated fields of cotton, used for nets. There are almost no weapons, walls or signs of war.', ev: ['caralnortechico'] },
  'civ:Minoans': { txt: 'The Minoans lived on Crete between about 2000 and 1450 BC, around great complexes such as Knossos, with storerooms, workshops and wall paintings; the name, after the mythical King Minos, was given by the archaeologist Arthur Evans. They were seafarers and traders in the Aegean, and their script, Linear A, has not been deciphered. Kings hardly appear in their images, and some argue that women held a central place in power, which others dispute. Around 1450 BC the Mycenaean Greeks took over the island.', ev: ['knossos'] },
  'civ:Shang': { txt: 'The Shang dynasty ruled the Yellow River valley, in northern China, between about 1600 and 1046 BC, with its final capital at Yin, near today’s Anyang. The Shang left the oracle bones, shells and bones used to consult the ancestors, which bear the oldest known Chinese writing. They were masters of bronze vessels and buried their kings with hundreds of sacrificed people. They were overthrown by the Zhou in 1046 BC.' },
  'civ:Hittites': { txt: 'The Hittites ruled central Anatolia between about 1600 and 1180 BC, with their capital at Hattusa, and spoke the oldest Indo-European language with a written record. They fought Egypt for Syria: after the Battle of Kadesh, around 1274 BC, they signed with Ramesses II one of the oldest known peace treaties. The kingdom fell around 1180 BC, in the collapse that struck the whole eastern Mediterranean, whose causes are still debated.' },
  'civ:Olmecs': { txt: 'The Olmecs lived in the lowlands of the Gulf of Mexico, between Veracruz and Tabasco, from about 1200 to 400 BC, in centres such as San Lorenzo and La Venta. They are known for their colossal basalt heads, which probably portray rulers, and for an art of jaguars and baby-like figures. For a long time they were called the "mother culture" of Mesoamerica; today many archaeologists prefer to speak of several sister cultures that exchanged ideas. The Mesoamerican ball game and calendar already appear among them.', ev: ['maya'] },
  'civ:Phoenicians': { txt: 'The Phoenicians lived in city-states on the coast of today’s Lebanon, such as Tyre, Sidon and Byblos, and never formed a single country. Between about 1100 and 300 BC they were the great seafarers and traders of the Mediterranean, selling cedar wood and purple-dyed cloth and founding colonies such as Carthage and Cádiz. The Phoenician alphabet, of about 22 letters, gave rise to the Greek and Latin alphabets. The cities fell to the Assyrians, Babylonians and Persians, and Alexander took Tyre in 332 BC.', ev: ['alexander'] },
  'civ:Maya': { txt: 'The Maya never formed a single empire: between about 1000 BC and the Spanish conquest they lived in dozens of rival city-states in southern Mexico, Guatemala and Belize, such as Tikal, Calakmul, Palenque and Copán. They created the most complete writing system in the Americas, largely deciphered only from the 1970s, as well as calendars and a mathematics with zero. The great southern cities were abandoned in the 9th century, but those in the north of Yucatán carried on. The last independent Maya kingdom fell in 1697, and millions of people speak Maya languages today.', ev: ['maya'] },
  'civ:Chavín': { txt: 'The Chavín culture flourished in the Andes of northern Peru between about 900 and 200 BC, around the temple of Chavín de Huántar, with underground galleries and the stone sculpture called the Lanzón. The temple drew pilgrims from far away, and its style of felines, serpents and birds of prey spread through the highlands and the coast. There is no sign of a military empire: its influence seems to have been mainly religious.' },
  'civ:Nok': { txt: 'The Nok culture, in central Nigeria today, is known for its terracotta heads and figures, made between about 900 BC and AD 300. Its craftsmen were among the first to smelt iron in West Africa. Little is known about how they lived and governed themselves, partly because many sites were looted for the art market.' },
  'civ:Greeks': { txt: 'Between about 800 and 146 BC the Greeks lived in hundreds of independent city-states, the poleis, spread from Asia Minor to Sicily and the Black Sea, with very different governments: kings, oligarchies, tyrants, democracies. Together they beat the Persians in 490 and 480 BC and then fought each other. The Macedon of Philip and Alexander dominated them and carried the Greek language as far as Egypt and Central Asia. In 146 BC Rome destroyed Corinth and took Greece.', ev: ['athens', 'alexander'] },
  'civ:Persia': { txt: 'From 550 BC to AD 651 the Iranian plateau was the centre of great empires. The Achaemenids of Cyrus the Great ruled from Egypt to the Indus, with roads, a postal system and respect for local religions and laws, until Alexander defeated them in 330 BC. Then came the Parthians, rivals of Rome, and from AD 224 the Sasanians, with Zoroastrianism as the official religion. Muslim Arab armies overthrew the Sasanians in 651.', ev: ['alexander', 'baghdad'] },
  'civ:Rome': { txt: 'Rome was a republic from 509 BC to 27 BC, governed by elected consuls, an aristocratic Senate and assemblies, and then an empire ruled by emperors. At its height, in the 2nd century, it stretched from Scotland to Iraq and had perhaps 60 million inhabitants, millions of them enslaved. In 395 the empire was split in two; the western half ended in 476, when the last emperor was deposed, and the eastern half lasted another thousand years in Constantinople.', ev: ['romanrepublic', 'fallofrome'] },
  'civ:Maurya': { txt: 'The Maurya Empire, founded by Chandragupta Maurya around 322 BC with its capital at Pataliputra (today’s Patna), was the first to unify almost the whole Indian subcontinent. The emperor Ashoka, after a bloody war in Kalinga, embraced Buddhism and had edicts calling for tolerance and compassion carved on rocks and pillars. The empire broke up after him, and the last Maurya king was killed by his general in 185 BC.' },
  'civ:Han': { txt: 'The Han dynasty ruled China from 206 BC to AD 220, in an era so formative that most Chinese still call themselves the "Han people". It built a bureaucracy based on the texts of Confucius and monopolies on salt and iron, and opened routes to Central Asia, the so-called Silk Road. Paper was invented in Han times. Peasant revolts and rival generals split the empire into three kingdoms in 220.', ev: ['hansilkroad'] },
  'civ:Aksum': { txt: 'The kingdom of Aksum, in northern Ethiopia and Eritrea, controlled the Red Sea trade between about AD 100 and 940 through the port of Adulis, linking Rome, Arabia and India. It minted gold coins and raised enormous stone stelae. Around 330 King Ezana converted to Christianity, making Aksum one of the first states to do so. The kingdom declined when the Red Sea trade changed hands after the 7th century.' },
  'civ:Teotihuacan': { txt: 'Teotihuacan, in the Valley of Mexico, was between about AD 100 and 550 one of the largest cities in the world, with nearly 100,000 inhabitants, and its influence reached the Maya cities. Graeber and Wengrow stress that after about AD 300 the city invested in good-quality housing compounds for almost everyone, and there are no portraits of kings or clear royal tombs. Around 550 the centre was burned and the city emptied.', ev: ['teotihuacan'] },
  'civ:Moche': { txt: 'The Moche lived in the valleys of Peru’s northern coast between about AD 100 and 800, with irrigation canals, great adobe pyramids such as the Huaca del Sol and pottery that portrays faces, diseases and rituals with great realism. They were probably not a single state but several centres sharing one culture. In 1987 the intact tomb of the Lord of Sipán was found. Strong El Niño events in the 6th century may have helped bring about their decline.' },
  'civ:Byzantium': { txt: 'Byzantium is the name historians give to the Eastern Roman Empire, with its capital at Constantinople, from 395 to 1453; its people spoke Greek and called themselves Romans. Under Justinian, in the 6th century, it retook Italy and North Africa, but in the 7th century it lost Egypt and Syria to the Arabs. In 1204 Latin crusaders sacked the capital. What remained fell to the Ottomans in 1453.', ev: ['constantinople1453', 'fallofrome'] },
  'civ:Caliphate': { txt: 'After the death of the Prophet Muhammad in 632, his successors, the caliphs, conquered lands from Spain to Central Asia within a few decades. The Umayyad dynasty ruled from Damascus; in 750 the Abbasids overthrew it and in 762 founded Baghdad, one of the world’s centres of science and translation. Over time the caliphate broke up into local governments, and in 1258 the Mongols sacked Baghdad and killed the last Abbasid caliph of the city.', ev: ['baghdad', 'mongols'] },
  'civ:Tang': { txt: 'The Tang dynasty ruled China from 618 to 907, with its capital at Chang\'an, a city of about 1 million people where Persian, Sogdian and Arab merchants lived. It was an age of poetry, Buddhism and Silk Road trade, and the only woman to rule China as empress in her own right, Wu Zetian, reigned in this period. The An Lushan rebellion, from 755 to 763, killed millions and weakened the empire, which ended in 907.', ev: ['tangchangan'] },
  'civ:Ghana': { txt: 'Ancient Ghana, or Wagadu, was a Soninke kingdom between southern Mauritania and Mali today, well north of modern Ghana, which took its name in 1957. Between about 700 and 1240 it grew rich by taxing the gold from the south and the salt from the Sahara, carried by caravans to North Africa. The Arab geographer al-Bakri described it in 1068. The kingdom declined in the 12th century and was absorbed by Mali.', ev: ['mansamusa'] },
  'civ:Khmer': { txt: 'The Khmer Empire began around 802, when Jayavarman II declared himself universal king in what is now Cambodia, and lasted until 1431. Its capital, Angkor, was surrounded by reservoirs and canals that irrigated rice fields and covered a huge area. The kings built Hindu and later Buddhist temples, such as Angkor Wat and the Bayon. Droughts, floods and wars with the Thai kingdom of Ayutthaya, which sacked Angkor in 1431, drove the capital south.' },
  'civ:Vikings': { txt: 'The Vikings were Scandinavians who set out on raiding and trading expeditions between the attack on the monastery of Lindisfarne in 793 and the Norwegian defeat in England in 1066. They reached Baghdad by the rivers of Russia, settled Iceland and Greenland and, around the year 1000, camped in Newfoundland, in Canada. At home they settled disputes and made laws in assemblies of free men, the thing; Iceland’s, the Althing, has existed since 930.', ev: ['althing'] },
  'civ:Mali': { txt: 'The Mali Empire was founded around 1235 by Sundiata Keita, who defeated the king of Sosso at the Battle of Kirina, according to the oral tradition of the griots. It controlled the gold and trade of the Sahel, with cities such as Timbuktu and Djenné, centres of Islamic learning. In 1324 Mansa Musa went to Mecca with so much gold that he brought down its price in Cairo. The empire shrank in the 15th century before the rise of Songhai.', ev: ['mansamusa'] },
  'civ:Mongols': { txt: 'In 1206 an assembly of steppe chiefs proclaimed Temujin as Genghis Khan; he and his heirs created the largest contiguous empire in history, from Korea to Hungary. The conquests killed millions, but afterwards the empire protected the trade routes of Eurasia, along which merchants, ideas and probably also the Black Death travelled. Around 1260 the empire split into four khanates, and in 1368 the Mongols were driven out of China.', ev: ['mongols', 'blackdeath'] },
  'civ:Ottoman Empire': { txt: 'The Ottoman Empire was born around 1299 with Osman, chief of a small Turkish principality in Anatolia, and took Constantinople in 1453. In the 16th century, under Suleiman, it stretched from Hungary to Iraq and North Africa, and each religious community had its own laws and leaders. It lost territory throughout the 19th century, entered the First World War on Germany’s side and, during the war, committed the Armenian genocide. The sultanate was abolished in 1922.', ev: ['constantinople1453', 'ww1'] },
  'civ:Turkey': { txt: 'The Republic of Turkey was proclaimed in 1923 by Mustafa Kemal, later called Atatürk, on what was left of the Ottoman Empire. He separated religion and state, replaced the Arabic alphabet with the Latin one in 1928 and gave women the vote in 1934. In the year of its founding, about 1.5 million people were forcibly exchanged with Greece. Turkey joined NATO in 1952 and had military coups in 1960, 1971 and 1980.', ev: ['ww1', 'coldwar'] },
  'civ:Ming': { txt: 'The Ming dynasty was founded in 1368 by Zhu Yuanzhang, a peasant who led the rebellion that drove the Mongols out of China. The Yongle Emperor moved the capital to Beijing, built the Forbidden City and sent Zheng He’s fleets to the Indian Ocean; most of the Great Wall seen today dates from this period. The economy came to depend on silver from the Americas, which arrived on the Manila galleon. In 1644 rebels took Beijing, and the Manchus seized the chance to conquer the country.', ev: ['zhenghe', 'manila'] },
  'civ:Qing': { txt: 'The Qing dynasty, of Manchu origin, ruled China from 1644 to 1912 and brought it to the largest size in its history, including Tibet, Xinjiang, Mongolia and Taiwan. In the 19th century, defeats in the Opium Wars and the Taiping Rebellion, which killed perhaps 20 million people, weakened the empire. A revolution in 1911 overthrew the dynasty, and the last emperor, the boy Puyi, abdicated in February 1912.', ev: ['opium', 'taiping'] },
  'civ:Republic of China': { txt: 'The Republic of China was proclaimed in 1912, after the fall of the Qing, with Sun Yat-sen as its central figure. In the following years the country was divided among warlords, until Chiang Kai-shek’s Nationalist Party, the Kuomintang, reunified much of it in 1928. Japan invaded China in 1937, and the civil war with the Communists ended in 1949 with the government’s flight to Taiwan, where the republic continues.', ev: ['china1949'] },
  'civ:China': { txt: 'Mao Zedong proclaimed the People’s Republic of China on 1 October 1949, after the Communist victory in the civil war. The Great Leap Forward caused a famine between 1959 and 1961 that killed tens of millions of people, and the Cultural Revolution (1966–1976) persecuted millions. From 1978 Deng Xiaoping opened the economy to the market, and the country grew very fast; in 1989 the government put down the Tiananmen Square protests with gunfire.', ev: ['china1949', 'coldwar'] },
  'civ:Joseon (Korea)': { txt: 'The Joseon dynasty ruled Korea from 1392 to 1897, with a state organised on the ideas of Confucius and an elite of scholars, the yangban. In 1443 King Sejong created hangul, the Korean alphabet. The kingdom withstood the Japanese invasions of 1592 to 1598, partly thanks to Admiral Yi Sun-sin, and afterwards largely closed itself off from the outside world. In 1897 it became the Korean Empire, which Japan annexed in 1910.' },
  'civ:Japan (shogunate)': { txt: 'In 1603 Tokugawa Ieyasu received the title of shogun, the military chief who ruled in the emperor’s name, and his family held power in Edo (today’s Tokyo) until 1868. It was more than 250 years without internal wars, with regional lords obliged to spend years in the capital. The shogunate expelled the missionaries, banned Christianity and limited trade with Europeans to the Dutch, on an island in the port of Nagasaki. Perry’s American ships, in 1853, forced the ports open and set off the crisis that led to the Meiji Restoration.', ev: ['meiji'] },
  'civ:Mughals': { txt: 'The Mughal Empire was founded in 1526 by Babur, a Central Asian prince descended from Tamerlane and Genghis Khan, who defeated the sultan of Delhi at Panipat. Akbar (1556–1605) ruled with religious tolerance over a mostly Hindu empire led by a Muslim elite, and Shah Jahan built the Taj Mahal. After Aurangzeb died in 1707 the empire broke apart, and the English East India Company gradually took power. The British exiled the last emperor after the great revolt of 1857.', ev: ['plassey'] },
  'civ:British India': { txt: 'After the great revolt of 1857, the British Crown took the government of India away from the East India Company and ruled it directly, the so-called Raj, which included today’s Pakistan and Bangladesh. India supplied the empire with cotton, tea, opium, taxes and soldiers, and suffered enormous famines, such as the Bengal famine of 1943. The Indian National Congress, founded in 1885, and later Gandhi led the struggle for independence, won in 1947 with the partition of the territory.', ev: ['saltmarch', 'india1947'] },
  'civ:India': { txt: 'India became independent on 15 August 1947, separated from Pakistan in a partition that uprooted more than 10 million people and killed hundreds of thousands, or more, in violence between religions. With the 1950 Constitution, written under the leadership of B. R. Ambedkar, it became a democratic republic, today the world’s largest by number of voters. Jawaharlal Nehru governed until 1964; his daughter Indira Gandhi suspended civil liberties between 1975 and 1977.', ev: ['india1947'] },
  'civ:Safavid Persia': { txt: 'The Safavid dynasty, founded in 1501 by Shah Ismail I, unified Iran and made Shia Islam the official religion, which still shapes the country today. Shah Abbas I (1588–1629) moved the capital to Isfahan, filled it with mosques, palaces and squares, and fought the Ottomans over territory. In 1722 Afghan troops took Isfahan, and the dynasty effectively ended in 1736, when Nader Shah took the throne.' },
  'civ:Persia (Iran)': { txt: 'From the end of the 18th century the Qajar dynasty ruled Persia, which lost the Caucasus to Russia and had a constitutional revolution between 1905 and 1911. In 1925 Reza Pahlavi took the throne, and in 1935 he asked that the country be called Iran abroad. In 1953 the CIA and the British secret service helped overthrow Prime Minister Mossadegh, who had nationalised the oil. The 1979 revolution overthrew the shah and created the Islamic Republic, which soon faced Iraq in a war from 1980 to 1988.', ev: ['oil1973', 'coldwar'] },
  'civ:Russia': { txt: 'In 1480 Ivan III of Moscow stopped paying tribute to the Golden Horde; his grandson Ivan IV was crowned tsar in 1547, and Russia expanded across Siberia to the Pacific. Peter the Great and Catherine II made it a European power, but peasant serfdom was abolished only in 1861. The 1917 revolution ended the empire. After the end of the Soviet Union in December 1991, Boris Yeltsin’s Russian Federation went through chaotic privatisation, a deep economic crisis and the war in Chechnya.', ev: ['russianrev1917', 'berlinwallfall'] },
  'civ:Soviet Union': { txt: 'The Union of Soviet Socialist Republics was created in 1922 by the Bolsheviks who won the Russian Civil War. Under Stalin, the forced collectivisation of the countryside caused famines, such as the one in Ukraine in 1932–1933, and millions passed through the Gulag labour camps. In the Second World War it lost about 27 million people and was decisive in Germany’s defeat; afterwards it contested the world with the United States in the Cold War. It dissolved in December 1991.', ev: ['russianrev1917', 'ww2', 'coldwar', 'berlinwallfall'] },
  'civ:Habsburgs (Austria)': { txt: 'The Habsburg family, from Vienna, held the throne of the Holy Roman Empire almost without a break from the mid-15th century and gathered kingdoms mainly through marriages; Charles V came to rule Spain, the Americas, the Netherlands and Austria. The Austrian branch reigned over many peoples of central Europe, and in 1867 the empire became Austria-Hungary. Empress Leopoldina, wife of Pedro I of Brazil, was a Habsburg. The assassination of the heir Franz Ferdinand in 1914 led to the First World War, and the empire broke up in 1918.', ev: ['ww1', 'independence'] },
  'civ:Poland-Lithuania': { txt: 'The Commonwealth of the Two Nations was born from the Union of Lublin in 1569, between the Kingdom of Poland and the Grand Duchy of Lithuania, and was one of the largest states in Europe. The king was elected by the nobility, which, gathered in the Sejm (diet), could veto any law, and the Warsaw Confederation of 1573 guaranteed religious tolerance. In 1791 it adopted one of the first written constitutions in Europe. Russia, Prussia and Austria divided its territory in three partitions, the last in 1795.' },
  'civ:Sweden': { txt: 'In 1523 Gustav Vasa was elected king and took Sweden out of its union with Denmark; the crown soon adopted Lutheranism. In the 17th century, under Gustavus Adolphus, Sweden became a great power, fought in the Thirty Years’ War and dominated the Baltic, until it lost to Peter the Great’s Russia in 1709. After 1814 it fought no more wars, and in the 20th century it built a broad welfare state.', ev: ['westphalia'] },
  'civ:Prussia': { txt: 'The Kingdom of Prussia was created in 1701, with its capital in Berlin, and in the 18th century Frederick the Great made it a military power, known for its army and its strict bureaucracy. In 1848 its king crushed the revolution and refused the crown of a united Germany offered by an elected parliament. Under Chancellor Bismarck, Prussia defeated Denmark, Austria and France and created the German Empire in 1871, with its king as emperor.', ev: ['spring1848'] },
  'civ:Mamluks': { txt: 'The Mamluks were soldiers of slave origin, bought as boys in the steppes and the Caucasus and trained for war, who seized power in Egypt in 1250. In 1260 they defeated the Mongols at Ain Jalut, in Palestine, and ruled Egypt and Syria, with Cairo as one of the largest cities in the world. The sultanate was conquered by the Ottomans in 1516 and 1517.', ev: ['mongols', 'blackdeath'] },
  'civ:Morocco': { txt: 'In 1549 the Saadi dynasty took Fez and unified Morocco; in 1578, at the Battle of Alcácer Quibir, it defeated the Portuguese and killed King Sebastian. The Alawite dynasty, which still reigns today, came to power in the 1660s. Morocco was one of the last African countries to lose its independence: France and Spain divided it into protectorates in 1912, and it became independent again in 1956.', ev: ['alcacer'] },
  'civ:Songhai': { txt: 'The Songhai Empire, with its capital at Gao on the Niger River, grew under Sonni Ali, who took Timbuktu in 1468, and under Askia Muhammad, who extended control over the Sahel trade and supported Islamic learning. It was the largest state in the history of West Africa. In 1591 a Moroccan army with firearms defeated it at Tondibi, and the empire fell apart.', ev: ['mansamusa'] },
  'civ:Oyo': { txt: 'Oyo was a Yoruba empire in southwestern Nigeria today, whose strength came from its cavalry, and which between the 17th and 18th centuries dominated neighbouring kingdoms such as Dahomey. The king, the alafin, was watched by a council of chiefs, the Oyo Mesi, which could force him to kill himself, and by the Ogboni society. The empire collapsed around 1836, through internal wars and the advance of the Sokoto Caliphate. Many Yoruba, known in Brazil as Nagô, were sold to Bahia, and they were among the rebels of the Malê Revolt in 1835.', ev: ['slavetrade', 'males'] },
  'civ:Dahomey': { txt: 'Dahomey was a kingdom of the Fon people, with its capital at Abomey in today’s Benin, which in the 18th century took the port of Ouidah and became one of the largest sellers of captives to the Americas, many of them taken to Bahia. Its army had regiments of women warriors, the Agojie. The kingdom was a vassal of Oyo for much of the 18th century. France conquered it in 1894.', ev: ['slavetrade', 'berlin1884'] },
  'civ:Ashanti': { txt: 'The Ashanti confederation was formed around 1701 by Osei Tutu, with its capital at Kumasi in today’s Ghana; the Golden Stool, which according to tradition came down from the sky, symbolises the unity of the people. It grew rich on gold, kola nuts and the slave trade. It fought several wars against the British during the 19th century; after the 1900 revolt led by the queen mother Yaa Asantewaa, it was annexed in 1901.', ev: ['slavetrade', 'berlin1884'] },
  'civ:Ethiopia': { txt: 'In 1270 Yekuno Amlak founded the Solomonic dynasty, which claimed descent from King Solomon and the Queen of Sheba and ruled the Christian kingdom of Ethiopia for more than 700 years. In 1896 Emperor Menelik II defeated the Italian army at Adwa, and Ethiopia stayed independent during the Scramble for Africa, apart from the Italian occupation of 1936 to 1941. Haile Selassie was deposed in 1974 by a military junta, the Derg, which ruled by terror until 1991; in 1993 Eritrea broke away.', ev: ['adwa'] },
  'civ:Mutapa': { txt: 'The kingdom of Mutapa, or Monomotapa, was founded in the 15th century by Shona chiefs north of Great Zimbabwe, between today’s Zimbabwe and Mozambique, and controlled the gold sold to merchants on the coast. In the 16th century the Portuguese settled in the Zambezi valley and tried to dominate it, and in the 17th century they managed to impose allied kings. The kingdom kept losing land to the Rozvi state and was reduced to a small territory in the 18th century.', ev: ['zimbabwe'] },
  'civ:Zulu': { txt: 'The Zulu kingdom was created from 1816 by Shaka, who reorganised the army and united many clans of southeastern Africa by force, in a time of wars and migrations across the whole region. In 1879 the Zulus defeated a British army at Isandlwana, but lost the war months later at Ulundi. The kingdom was divided and, in 1897, annexed to the British colony of Natal.' },
  'civ:South Africa': { txt: 'The Union of South Africa was created in 1910 by joining British colonies and Boer republics, and was governed by whites alone. The Natives Land Act of 1913 reserved about 7% of the territory for the Black majority, and from 1948 the National Party imposed apartheid, the legal separation of races. After decades of resistance, as at Sharpeville in 1960 and Soweto in 1976, Nelson Mandela was released in 1990 and elected president in the first free elections, in 1994.', ev: ['apartheid'] },
  'civ:Nigeria': { txt: 'Nigeria became independent from Britain on 1 October 1960, bringing together in one country hundreds of peoples, such as the Yoruba, Igbo and Hausa, who had been joined by colonisation. Between 1967 and 1970 the war against the secession of Biafra, in the southeast, caused a famine that killed perhaps 1 million people. Oil became the country’s greatest source of wealth, and it lived under military governments almost continuously until 1999.', ev: ['decolonization1960'] },
  'civ:Algeria': { txt: 'France conquered Algeria from 1830 on and treated it as part of France itself, with about 1 million European settlers. The war of independence, led by the National Liberation Front between 1954 and 1962, killed hundreds of thousands of people and saw systematic torture by the French army. Algeria became independent on 5 July 1962, under a single party; in the 1990s, after elections that the Islamists were about to win were cancelled, it went through a civil war.', ev: ['decolonization1960'] },
  'civ:Ayutthaya (Siam)': { txt: 'The kingdom of Ayutthaya was founded in 1351 on an island in the Chao Phraya River, in today’s Thailand, and became a great port for rice and trade, with quarters for Portuguese, Dutch, Japanese, Persians and Chinese. Its armies sacked Angkor in 1431. In 1767 the city was razed by a Burmese army, and the kingdom came to an end.' },
  'civ:Siam (Thailand)': { txt: 'In 1782 the general who became King Rama I founded the Chakri dynasty, which still reigns today, and the new capital, Bangkok. Siam was the only country in Southeast Asia never to become a European colony: it gave up territory and remained a buffer zone between British Burma and French Indochina. In 1932 a revolt turned the country into a constitutional monarchy, and in 1939 it was renamed Thailand; since then it has had many military coups.' },
  'civ:Dai Viet': { txt: 'Dai Viet was the name of the Vietnamese state; in 1428 Lê Lợi drove out the Chinese of the Ming dynasty and founded the Lê dynasty. In the following centuries the kingdom pushed south, absorbing the kingdom of Champa and the Mekong delta, but it split between two rival families, the Trịnh in the north and the Nguyễn in the south. After the Tây Sơn revolt, which began in 1771, Nguyễn Ánh unified the country in 1802 and began calling it Vietnam.' },
  'civ:Dutch East Indies': { txt: 'When the Dutch East India Company went bankrupt in 1799, the Dutch state took over its possessions in the archipelago of today’s Indonesia. From 1830 the "cultivation system" forced the peasants of Java to grow coffee, sugar and indigo for the government, which enriched the Netherlands and caused famines. The conquest of the other islands was completed only in the early 20th century, after a long war in Aceh. Japan occupied the colony from 1942 to 1945.', ev: ['vocamsterdam'] },
  'civ:Indonesia': { txt: 'Sukarno proclaimed Indonesia’s independence on 17 August 1945, just after the Japanese surrender, and the country fought the return of the Dutch until 1949. In 1965 and 1966, after an attempted coup, the army and militias killed hundreds of thousands of people accused of communism, and General Suharto ruled as dictator until 1998. In 1975 Indonesia invaded East Timor.', ev: ['decolonization1960', 'coldwar'] },
  'civ:Australia': { txt: 'Aboriginal peoples have lived in Australia for at least 50,000 years. In 1788 the British First Fleet arrived at Sydney Cove with about a thousand people, most of them convicts, and began a colonisation that, through frontier wars and epidemics, greatly reduced the Aboriginal population. The colonies joined in a federation in 1901, which for decades restricted immigration to whites. Only in 1992, in the Mabo case, did the courts recognise that Aboriginal people had rights to the land that predated British arrival.' },
};

/* ---------- empires and states from the thread maps (history.js) and the eras (eras.js) ---------- */
const ST = {
  /* Andes before the Incas */
  'st:Moche': { txt: 'The Moche lived in the valleys of Peru’s northern coast between about AD 100 and 800, with irrigation canals, adobe pyramids and very realistic pottery. They were probably several centres sharing one culture rather than a single state. Droughts and floods linked to El Niño may have contributed to their decline.' },
  'st:Wari': { txt: 'The Wari state, with its capital near today’s Ayacucho in the Peruvian Andes, dominated much of the Peruvian highlands between about AD 600 and 1000. It built administrative centres linked by roads and used knotted cords, forerunners of the Inca quipus. Many archaeologists see it as the first Andean empire, although how centralised it was is debated.' },
  'st:Tiwanaku': { txt: 'Tiwanaku, near Lake Titicaca in today’s Bolivia, was between about AD 500 and 1000 a great religious and political centre, with stone temples such as the Gate of the Sun. It was sustained by raised fields between canals, which protected the crops from frost, and by llama caravans that carried its influence to Chile and Peru. It declined after 1000, perhaps because of a long drought.' },
  'st:Chimú': { txt: 'The Chimú kingdom dominated Peru’s northern coast between about 900 and 1470, with its capital at Chan Chan, the largest adobe city in the Americas. It inherited irrigation techniques from the Moche and was famous for its goldsmiths. The Incas conquered it around 1470 and took its craftsmen to Cusco.' },

  /* Europe, Africa and the Americas in the time of the thread */
  'st:Portugal': { txt: 'The kingdom of Portugal has existed since the 12th century and has had practically the same borders since the late 13th century. Starting with the capture of Ceuta in 1415, it built a maritime empire with trading posts in Africa and Asia and colonies in Brazil, Angola and Mozambique. It lost Brazil in 1822; in 1910 it became a republic, and from 1933 to 1974 it lived under Salazar’s Estado Novo dictatorship. The Carnation Revolution of 25 April 1974 ended the dictatorship and the colonial wars in Africa.', ev: ['cabral', 'iberianunion', 'junot', 'independence'] },
  'st:Castile and Aragon': { txt: 'The marriage of Isabella of Castile and Ferdinand of Aragon in 1469 joined the two crowns, which kept separate laws and institutions. The Catholic Monarchs created the Spanish Inquisition in 1478 and, in 1492, took Granada, expelled the Jews and financed Columbus’s voyage. In 1494 they divided the world still to be discovered with Portugal in the Treaty of Tordesillas.', ev: ['columbus1492', 'tordesillas'] },
  'st:France': { txt: 'The kingdom of France came out of the Hundred Years’ War in 1453 as one of the strongest monarchies in Europe. It challenged the Treaty of Tordesillas, traded brazilwood with the Tupinambá and attempted colonies in Rio de Janeiro in 1555 and in Maranhão in 1612. The Revolution of 1789 ended the absolute monarchy; then came Napoleon, new monarchies and, from 1870, the republic, at the head of a great colonial empire in Africa and Asia.', ev: ['franceantarctique', 'france1789', 'napoleon', 'junot'] },
  'st:England': { txt: 'The kingdom of England, under the Tudors and the Stuarts, broke with Rome in 1534, fought Spain at sea and founded colonies in North America and the Caribbean in the 17th century. A civil war (1642–1651) and the Glorious Revolution of 1688 gave Parliament power over the king. In 1703 it signed the Methuen Treaty with Portugal, and in 1707 it united with Scotland to form Great Britain.', ev: ['gloriousrev', 'methuen'] },
  'st:Kongo': { txt: 'The kingdom of Kongo, with its capital at Mbanza Kongo in northern Angola today, was one of the largest states in Central Africa when the Portuguese arrived in 1483. Its kings converted to Catholicism and exchanged embassies with Lisbon and Rome; in 1526 Afonso I wrote to the king of Portugal complaining that the slave trade was depopulating the country. In 1665 the Portuguese of Angola defeated Kongo at Mbwila, and the kingdom split in civil wars. At the end of the 19th century it was divided among Portugal, Belgium and France.', ev: ['kongo', 'luanda', 'slavetrade'] },
  'st:Inca (Tawantinsuyu)': { txt: 'Tawantinsuyu, "the four parts together", was the name of the Inca state, with its capital at Cusco. In less than a century, starting with Pachacuti around 1438, it spread from southern Colombia to central Chile, with millions of inhabitants. There was no money and there were no markets as Europeans knew them: peasants paid the state with shifts of labour, the mit\'a, and accounts were kept in quipus, knotted cords. In the middle of a civil war between Huáscar and Atahualpa, Pizarro captured Atahualpa in 1532.', ev: ['inca', 'pizarro'] },
  'st:Mexica (Triple Alliance)': { txt: 'In 1428 the cities of Tenochtitlan, Texcoco and Tlacopan, in the Valley of Mexico, formed an alliance that collected tribute from dozens of Mesoamerican peoples; Tenochtitlan, on an island in the lake, had perhaps 200,000 inhabitants. Many subject or enemy peoples, such as those of Tlaxcala, which was governed by a council, allied with the Spanish. With them, and with smallpox, Hernán Cortés took Tenochtitlan in 1521.', ev: ['tenochtitlan', 'tlaxcala', 'cortes'] },
  'st:Castile in the Caribbean': { txt: 'After 1492 Castile occupied the island it called Hispaniola, today divided between Haiti and the Dominican Republic, and founded Santo Domingo in the 1490s. The Taíno were parcelled out among settlers for forced labour, the encomienda, and died in huge numbers from violence, hunger and disease. The first enslaved Africans reached the island as early as the beginning of the 16th century.', ev: ['columbus1492'] },
  'st:Spain': { txt: 'Under Charles I, from 1516, the crowns of Castile and Aragon had a single king, and Spain built an empire stretching from Mexico and Peru to the Philippines, sustained by the silver of Potosí and Mexico. From 1580 to 1640 its kings also ruled Portugal. Napoleon invaded it in 1808, and between 1810 and 1825 almost all of Spanish America became independent; in 1898 it lost Cuba, Puerto Rico and the Philippines. In the 20th century it went through the Civil War (1936–1939) and Franco’s dictatorship, until 1975.', ev: ['potosi', 'iberianunion', 'spain1808', 'bolivar'] },
  'st:Portugal (under the Spanish king)': { txt: 'After King Sebastian died at Alcácer Quibir in 1578, and his great-uncle, Cardinal Henry, died without heirs, Philip II of Spain became king of Portugal in 1580. Under the agreement of the Cortes of Tomar, Portugal kept its own laws, language and government. As enemies of Spain, the Dutch began attacking the Portuguese colonies, including Brazil. On 1 December 1640 Portuguese nobles acclaimed the Duke of Braganza as King John IV.', ev: ['alcacer', 'iberianunion', 'dutch', 'restoration'] },
  'st:United Provinces': { txt: 'The United Provinces, or Dutch Republic, were born from the revolt of the northern provinces of the Netherlands against Spain from 1568, and were recognised as independent in 1648. They were a republic of cities and provinces with a States General and no king, and in the 17th century they had the largest merchant fleet in Europe and the East and West India Companies. The republic ended in 1795, when the French invaded it.', ev: ['vocamsterdam', 'dutch', 'westphalia'] },
  'st:Dutch West India Company': { txt: 'The West India Company (WIC), created in 1621 by Dutch merchants to attack the Iberian empire in the Atlantic, took Salvador in 1624, for a year, and Olinda and Recife in 1630. Under Count John Maurice of Nassau, between 1637 and 1644, it governed the sugar-growing Northeast and took Luanda to secure enslaved Africans for the sugar mills. The mill owners revolted in 1645, and the company surrendered in 1654.', ev: ['dutch', 'luanda1641', 'vocamsterdam'] },
  'st:England in the Caribbean': { txt: 'The English occupied Barbados in 1627, and in the 1640s the planters switched to sugar, with techniques and enslaved people brought partly from Dutch Brazil. In 1655 an English expedition took Jamaica from Spain. These islands became sugar factories run by enslaved Africans, who made up the great majority of the population.', ev: ['caribbean'] },
  'st:Great Britain': { txt: 'The kingdom of Great Britain was created in 1707 by the union of England and Scotland. It beat France in the Seven Years’ War (1756–1763), gaining Canada and dominance in India, but lost the Thirteen Colonies, which became the United States. The Industrial Revolution began there, and Brazilian gold, arriving through Lisbon, helped pay for its imports from Portugal. In 1801 it united with Ireland, forming the United Kingdom.', ev: ['industrialrev', 'usa', 'methuen'] },
  'st:France in the Caribbean': { txt: 'The French colonies in the Caribbean were Martinique, Guadeloupe and, above all, Saint-Domingue, the western side of the island of Hispaniola, ceded by Spain in 1697. In the 18th century Saint-Domingue was the most profitable colony in the world, the largest producer of sugar and coffee, with about half a million enslaved Africans. In 1791 they rose up and, in 1804, created Haiti.', ev: ['haiti', 'caribbean'] },
  'st:Great Britain in the Caribbean': { txt: 'In the 18th century Jamaica, Barbados and the Leeward Islands were Britain’s most valuable colonies, thanks to the sugar produced by hundreds of thousands of enslaved Africans. The plantation owners had members in the Parliament in London. Revolts were frequent, such as Tacky’s Revolt in Jamaica in 1760.', ev: ['caribbean', 'abolition1807'] },
  'st:Portugal and Brazil': { txt: 'Between 1808 and 1821 the capital of the Portuguese empire was Rio de Janeiro: the court fled Lisbon ahead of the French invasion and opened Brazil’s ports to foreign trade. In 1815 Brazil was raised to a kingdom united with Portugal and the Algarves, while Portugal was run by a regency under heavy British tutelage. The Porto Revolution of 1820 demanded the king’s return, and John VI went back to Lisbon in 1821.', ev: ['court', 'openports', 'unitedkingdom', 'return'] },
  'st:Spain (occupied by Napoleon)': { txt: 'In 1808 Napoleon forced the Spanish monarchs to abdicate at Bayonne and put his brother Joseph Bonaparte on the throne. The Spanish rose up in Madrid on 2 May, and the guerrilla war, with British support, lasted until 1814. With no legitimate king, governing juntas took power in Spain and in America, and in 1812 the Cortes of Cádiz adopted a liberal constitution. It was this power vacuum that set off the independence movements of Spanish America.', ev: ['spain1808', 'buenosaires', 'hidalgo'] },
  'st:French Empire': { txt: 'Napoleon Bonaparte crowned himself Emperor of the French in 1804 and within a few years dominated most of continental Europe, putting relatives on several thrones. In 1806 he decreed the Continental System against Britain, and to close it he invaded Portugal in 1807; he had also restored slavery in the French colonies in 1802. The Russian campaign of 1812 destroyed his army, and he was finally defeated at Waterloo in 1815.', ev: ['napoleon', 'blockade', 'junot', 'vienna'] },
  'st:United Kingdom': { txt: 'The United Kingdom of Great Britain and Ireland was created in 1801; since 1922 only Northern Ireland has remained in it. In 1807 it banned the slave trade and in 1833 abolished slavery in its colonies, and it began pressing Brazil to end the trade, even with the Aberdeen Act of 1845. In the 19th century it was the greatest industrial and naval power, creditor to Brazil and all of Latin America. After the Second World War it lost almost all of its empire.', ev: ['abolition1807', 'treaties1810', 'aberdeen', 'ww2'] },
  'st:Holland (under France)': { txt: 'After the French invasion of 1795, the Dutch Republic became the Batavian Republic, a state allied with France. In 1806 Napoleon turned it into the Kingdom of Holland for his brother Louis Bonaparte, and in 1810 he annexed it to France. Independence returned in 1813, with Napoleon’s defeat.', ev: ['napoleon'] },
  'st:Haiti': { txt: 'Haiti was born from the largest slave revolt in history, begun in Saint-Domingue in 1791 and led by Toussaint Louverture and then by Jean-Jacques Dessalines, who declared independence on 1 January 1804. It was the first country founded by people who had been enslaved and the first in the Americas to abolish slavery for good. In 1825 France demanded a huge indemnity in exchange for recognition, which Haiti paid for more than a century. The United States occupied the country from 1915 to 1934, and the Duvalier family ruled it as a dictatorship from 1957 to 1986.', ev: ['haiti'] },
  'st:United Kingdom in the Caribbean': { txt: 'In the early 19th century the United Kingdom added to its Caribbean islands territories taken from rivals, such as Trinidad, taken from Spain in 1797. The slave trade was banned in 1807, but slavery continued until 1834, followed by a forced "apprenticeship" until 1838. Slave owners received 20 million pounds in compensation from the British government; the freed people received nothing.', ev: ['abolition1807', 'caribbean'] },
  'st:Upper Peru (royalist until 1825)': { txt: 'Upper Peru, with Potosí and Chuquisaca, was one of the first regions to form governing juntas, in 1809, but also the last stronghold of the armies loyal to the king of Spain in South America. Only after Sucre’s victory at Ayacucho in 1824 did the region become independent, in 1825, under the name Bolivia, in honour of Bolívar.', ev: ['potosi', 'bolivar'] },
  'st:Peru': { txt: 'Lima was the capital of the richest Spanish viceroyalty in South America, and the city’s elite was slow to support independence, proclaimed by San Martín in 1821 and secured at Ayacucho in 1824. In the 19th century the country grew rich on guano and lost its nitrate provinces to Chile in the War of the Pacific (1879–1884). At the end of the 20th century it went through the war against the Shining Path and Fujimori’s authoritarian government.', ev: ['bolivar', 'tupacamaru'] },
  'st:Paraguay': { txt: 'Paraguay broke away from Spain and from Buenos Aires in 1811 and, under the dictator José Gaspar de Francia (1814–1840), lived almost cut off from the world. In the War of the Triple Alliance (1864–1870), against Brazil, Argentina and Uruguay, it lost territory and a huge part of its population; estimates range from about a quarter to more than half, and are much debated. In the 20th century it defeated Bolivia in the Chaco War (1932–1935) and lived under Stroessner’s long dictatorship (1954–1989).', ev: ['paraguaywar'] },
  'st:Empire of Brazil': { txt: 'The Empire of Brazil lasted from 1822 to 1889, a monarchy on a continent of republics. The 1824 Constitution gave the emperor the Moderating Power, above the other branches; Pedro I abdicated in 1831, and after the revolts of the Regency, Pedro II reigned from 1840 to 1889. The economy depended on coffee and slave labour: the slave trade ended only in 1850 and slavery in 1888. A military coup proclaimed the republic on 15 November 1889.', ev: ['independence', 'abdication', 'paraguaywar', 'abolition'] },
  'st:United Provinces of the Río de la Plata': { txt: 'The United Provinces of the Río de la Plata were born from the May Revolution of 1810 in Buenos Aires and declared independence at Tucumán on 9 July 1816. The provinces fought among themselves: the Unitarians wanted a strong government in Buenos Aires, the Federalists wanted autonomy. The war against Brazil over the Cisplatina, from 1825 to 1828, ended with the independence of Uruguay.', ev: ['buenosaires', 'cisplatina'] },
  'st:Chile': { txt: 'Chile formed its first junta in 1810 and won independence in 1818, with O\'Higgins and San Martín. It had stable governments in the 19th century and, in the War of the Pacific (1879–1884), took the nitrate areas from Peru and Bolivia, along with the Bolivian coast. In 1970 it elected the socialist Salvador Allende, overthrown on 11 September 1973 by the coup of General Pinochet, who ruled until 1990.', ev: ['chile1973', 'bolivar'] },
  'st:Gran Colombia': { txt: 'The Republic of Colombia, which historians call Gran Colombia, was created by Simón Bolívar in 1819 and brought together today’s Colombia, Venezuela, Ecuador and Panama, with its capital at Bogotá. Disputes between the regions, and between Bolívar and his generals, broke it apart between 1830 and 1831, the year Bolívar died.', ev: ['bolivar'] },
  'st:British Guiana': { txt: 'The British took the colonies of Demerara, Essequibo and Berbice from the Dutch; they were ceded in 1814 and united in 1831 as British Guiana, a land of sugar plantations. After abolition, the British brought in indentured workers from India, who became the majority of the population. A border dispute with Brazil, the Pirara question, was arbitrated by the king of Italy in 1904, mostly in Britain’s favour. The colony became independent in 1966 as Guyana.', ev: ['abolition1807'] },
  'st:Suriname (Dutch)': { txt: 'Suriname passed from England to the Netherlands in 1667, in an exchange in which the English kept New Amsterdam, the future New York. Its sugar plantations were known for their cruelty, and many enslaved people fled into the forest, where Maroon peoples such as the Saramaka forced peace treaties from the Dutch in the 1760s. Slavery was abolished only in 1863, and afterwards indentured workers came from India and Java.', ev: ['palmares', 'caribbean'] },
  'st:French Guiana': { txt: 'French Guiana, with its capital at Cayenne, has been a French colony since the 17th century. Luso-Brazilian troops occupied it from 1809 to 1817, in response to Napoleon’s invasion of Portugal. From 1852 to 1953 it was a penal colony, home of Devil’s Island. The dispute with Brazil over Amapá was decided in Brazil’s favour in 1900; since 1946 French Guiana has been a department of France.', ev: ['court', 'junot'] },
  'st:Mexican Empire': { txt: 'After eleven years of war begun by the priest Hidalgo in 1810, Mexico became independent in 1821, and General Agustín de Iturbide was crowned emperor in 1822. The empire included Central America but did not last long: Iturbide abdicated in 1823, and Mexico became a republic.', ev: ['hidalgo'] },
  'st:United States': { txt: 'The United States declared independence in 1776 and, in the 19th century, pushed west by buying, conquering and driving out Indigenous peoples; in 1848 it took about half of Mexico’s territory. The Civil War (1861–1865) ended slavery, and by the early 20th century the country was already the largest economy in the world, with colonies such as Puerto Rico and the Philippines. After 1945 it was one of the two superpowers of the Cold War.', ev: ['usa', 'civilwar', 'crash29', 'coldwar'] },
  'st:British North America': { txt: 'After the independence of the United States, Britain kept its northern colonies: Quebec, divided into Upper and Lower Canada, Nova Scotia, New Brunswick and others, where many settlers loyal to the king went. To the north and west lay the lands of the Hudson’s Bay Company. After revolts in 1837 and 1838 the colonies gained self-government and, in 1867, united in the Dominion of Canada.', ev: ['usa'] },
  'st:Netherlands': { txt: 'The Kingdom of the Netherlands was created in 1815 at the Congress of Vienna and included Belgium until it broke away in 1830. It kept colonies such as the Dutch East Indies (Indonesia), Suriname and the Antilles. It stayed neutral in the First World War, was occupied by Germany in the Second, and helped found NATO and the European Community.', ev: ['vienna', 'vocamsterdam'] },
  'st:Bolivia': { txt: 'Bolivia, independent since 1825 and named in honour of Bolívar, lost territory in almost all of its wars: its coast to Chile in the War of the Pacific, Acre to Brazil in the Treaty of Petrópolis in 1903, and much of the Chaco to Paraguay in 1935. In 1952 a revolution nationalised the tin mines, carried out land reform and gave the vote to Indigenous people, the majority of the population.', ev: ['petropolis', 'bolivar'] },
  'st:Uruguay': { txt: 'The Banda Oriental was fought over by Spain and Portugal for centuries and annexed to Brazil as the Cisplatina Province in 1821. After the war between Brazil and Buenos Aires, it became independent in 1828, through British mediation. It went through long civil wars between Blancos and Colorados in the 19th century and, in the early 20th, under José Batlle, became one of the countries with the most social legislation in the Americas; it had a military dictatorship from 1973 to 1985.', ev: ['cisplatina', 'paraguaywar'] },
  'st:Mexico': { txt: 'After 1823 Mexico was an unstable republic and, between 1836 and 1848, lost Texas and about half its territory to the United States. Benito Juárez, a Zapotec Indigenous man, led the liberal reforms and the resistance to the French intervention (1862–1867). Porfirio Díaz’s dictatorship ended in the Revolution of 1910, and afterwards a single party, the PRI, ruled from 1929 to 2000; in 1994 the Zapatistas rose up in Chiapas.', ev: ['hidalgo', 'mexico1910', 'zapatistas'] },
  'st:United Provinces of Central America': { txt: 'In 1823 Guatemala, El Salvador, Honduras, Nicaragua and Costa Rica, which had been part of the Mexican Empire, formed a federal republic. Wars between liberals and conservatives, and between the provinces, broke it apart between 1838 and 1841. Since then the five have been separate countries.' },
  'st:Argentine Confederation': { txt: 'Between 1831 and 1852 the Argentine provinces formed a confederation dominated by Juan Manuel de Rosas, governor of Buenos Aires, who ruled with absolute powers. Rosas was overthrown at the Battle of Caseros in 1852 by Justo José de Urquiza, with troops from Brazil and Uruguay. The 1853 Constitution created a federation, but Buenos Aires stayed separate until 1861.', ev: ['buenosaires'] },
  'st:New Granada': { txt: 'The Republic of New Granada was the name of the country formed by today’s Colombia and Panama after the end of Gran Colombia, from 1831 to 1858. It went through wars between liberals and conservatives and changed its name and form of government several times, until it became the Republic of Colombia in 1886.', ev: ['bolivar'] },
  'st:Venezuela': { txt: 'Venezuela, Bolívar’s homeland, broke away from Gran Colombia in 1830 and was ruled by military caudillos for almost a century. From the 1920s it became one of the world’s largest oil exporters, under the dictatorship of Juan Vicente Gómez. After 1958 it had elected governments, and in 1960 it helped found OPEC.', ev: ['bolivar', 'oil1973'] },
  'st:Ecuador': { txt: 'Ecuador broke away from Gran Colombia in 1830, divided between the conservative highlands of Quito and the commercial port of Guayaquil. It exported cocoa, then bananas and, from the 1970s, oil. It fought border wars with Peru in 1941 and 1995, in which it lost much of the Amazonian land it claimed.', ev: ['bolivar'] },
  'st:Central American republics': { txt: 'After 1841 Guatemala, El Salvador, Honduras, Nicaragua and Costa Rica went on as separate republics, exporting coffee and, later, bananas from American companies such as United Fruit. The United States intervened many times, occupying Nicaragua from 1912 to 1933 and backing the coup in Guatemala in 1954. Between the 1970s and the 1990s, civil wars in Guatemala, El Salvador and Nicaragua killed hundreds of thousands of people.', ev: ['coldwar'] },
  'st:Dominican Republic': { txt: 'The eastern side of the island of Hispaniola was ruled by Haiti from 1822 to 1844, when it declared independence. Spain reannexed it between 1861 and 1865, and the United States occupied it from 1916 to 1924. Rafael Trujillo ruled as dictator from 1930 to 1961 and, in 1937, ordered the massacre of thousands of Haitians on the border.', ev: ['haiti'] },
  'st:Belgium': { txt: 'Belgium broke away from the Netherlands in 1830 and became a constitutional monarchy and one of the first industrial countries on the continent. Its king Leopold II held the Congo Free State as his personal property from 1885 to 1908, and forced rubber extraction killed and maimed an enormous number of people; afterwards the Congo was a Belgian colony until 1960. Belgium was invaded by Germany in both world wars.', ev: ['congofreestate', 'berlin1884'] },
  'st:Japan (Tokugawa shogunate)': { txt: 'From 1603 to 1868 Japan was ruled by the shoguns of the Tokugawa family, military chiefs who governed in the emperor’s name from Edo, today’s Tokyo. Trade with Europeans was limited to the Dutch, on an island in the port of Nagasaki. In 1853 the American ships of Commodore Perry forced the ports open, and the crisis that followed led to the Meiji Restoration.', ev: ['meiji'] },
  'st:Argentina': { txt: 'Unified from 1862, Argentina fought in the Paraguayan War and, between 1878 and 1885, took by force the lands of the Indigenous peoples of the Pampas and Patagonia. Millions of immigrants, mostly Italians and Spaniards, came to work on the cattle and wheat estancias and in the cities. In the 20th century Peronism shaped politics, and the 1976–1983 dictatorship made thousands of people disappear (human rights groups speak of 30,000) and lost the Falklands War in 1982.', ev: ['paraguaywar', 'immigration'] },
  'st:Colombia': { txt: 'Colombia took this name in 1886, after several constitutions and wars between liberals and conservatives; the Thousand Days’ War (1899–1902) was followed by the loss of Panama in 1903. Coffee became the main export. La Violencia, a war between the two parties from 1948 to 1958, killed about 200,000 people, and from the 1960s guerrilla groups such as the FARC emerged.', ev: ['bolivar'] },
  'st:Canada (British dominion)': { txt: 'The Dominion of Canada was created in 1867, self-governing but under the British Crown, and grew west to the Pacific with the help of a transcontinental railway. The expansion crushed the Métis revolts led by Louis Riel in 1870 and 1885, and sent Indigenous children to residential schools where many died. Canada fought in both world wars as part of the empire and gained full autonomy in 1931.' },
  'st:Italy': { txt: 'The Kingdom of Italy was proclaimed in 1861, uniting independent states by force under the House of Savoy; Rome became the capital in 1870. Rural poverty drove millions of Italians to emigrate, more than a million of them to Brazil, mostly to the coffee plantations of São Paulo. Italy attempted an empire in Africa, was defeated by Ethiopia at Adwa in 1896, and from 1922 to 1943 lived under Mussolini’s fascist dictatorship. In 1946 it became a republic.', ev: ['italy', 'immigration', 'adwa', 'feb'] },
  'st:German Empire': { txt: 'The German Empire was proclaimed on 18 January 1871 at Versailles, under the king of Prussia, after three wars won by Chancellor Bismarck. It quickly became an industrial power and, after the Berlin Conference of 1884–1885, took colonies in Africa and the Pacific; in German South West Africa, today’s Namibia, it committed the genocide of the Herero and Nama between 1904 and 1908. Defeated in the First World War, the empire ended with the abdication of Emperor Wilhelm II in November 1918.', ev: ['berlin1884', 'ww1'] },
  'st:Japan': { txt: 'After the Meiji Restoration in 1868, Japan industrialised quickly and became a colonial power: it took Taiwan in 1895, defeated Russia in 1905 and annexed Korea in 1910. In 1908 the first Japanese immigrants arrived in Brazil on the ship Kasato Maru. Military expansion across China and the Pacific ended in defeat in 1945, with the bombs of Hiroshima and Nagasaki. After the American occupation, with a new Constitution in 1947, it became one of the largest economies in the world.', ev: ['meiji', 'kasato', 'hiroshima1945'] },
  'st:Brazil': { txt: 'The Republic was proclaimed on 15 November 1889 by a military coup. Until 1930 the oligarchies of São Paulo and Minas Gerais took turns in power; then came Getúlio Vargas’s fifteen years, including the Estado Novo dictatorship, and the democracy of 1946. In 1964 a military coup installed a dictatorship that lasted until 1985, and the 1988 Constitution restored democracy.', ev: ['republic', 'rev1930', 'coup64', 'constitution'] },
  'st:Panama': { txt: 'Panama broke away from Colombia on 3 November 1903 with the support of the United States, which soon gained perpetual control of a strip of land to build the canal, opened in 1914. For decades the Canal Zone was practically American territory in the middle of the country. In 1989 the United States invaded Panama to arrest General Noriega, and the canal passed to the Panamanians at the end of 1999.' },
  'st:Cuba': { txt: 'Cuba was one of the last Spanish colonies in the Americas and abolished slavery only in 1886. After two wars of independence, the second led by José Martí, the United States intervened in 1898, and the republic was born in 1902 under American tutelage, which left behind the Guantánamo base. Fidel Castro’s Revolution of 1959 overthrew Batista’s dictatorship and allied the country with the Soviet Union.', ev: ['cuba1959', 'missiles1962'] },
  'st:Ireland': { txt: 'After the Easter Rising of 1916 and a war of independence against the British (1919–1921), 26 of the 32 Irish counties formed the Irish Free State in 1922; the mostly Protestant northeast stayed in the United Kingdom. A civil war followed between those who accepted the treaty and those who rejected it. Ireland declared itself a republic in 1949. In the 19th century the Great Famine had killed about 1 million people and driven another million to emigrate.' },
  'st:Germany': { txt: 'In 1930 Germany was the Weimar Republic, created after the defeat of 1918 and shaken by the inflation of 1923 and the crash of 1929. In January 1933 Adolf Hitler was appointed chancellor and within a few months set up the Nazi dictatorship. The regime led the world into the Second World War and murdered about 6 million Jews in the Holocaust, as well as Roma, disabled people and others. After its defeat in 1945 the country was occupied and divided in two, and was reunited only in 1990.', ev: ['crash29', 'ww2', 'holocaust', 'berlinwallfall'] },
  'st:Canada': { txt: 'Canada gained full legislative autonomy from Britain in 1931 and, in 1982, began amending its own Constitution, although the British monarch remains head of state. It is a bilingual country, in English and French; in 1980 and 1995 Quebec voted in referendums on whether to separate, and "no" won narrowly the second time. Indigenous peoples, called First Nations, continue to fight for land and redress.' },
  'st:East Germany': { txt: 'The German Democratic Republic was created on 7 October 1949 in the Soviet occupation zone, governed by a single party with Moscow’s backing. In 1953 a workers’ uprising was crushed by Soviet tanks, and in 1961 the regime built the Berlin Wall to stop people fleeing to the West. The political police, the Stasi, watched millions of people. After the protests of 1989 the wall fell, and the country joined West Germany in 1990.', ev: ['coldwar', 'berlinwallfall'] },
  'st:West Germany': { txt: 'The Federal Republic of Germany was created in May 1949 in the American, British and French occupation zones, with its capital in Bonn. With help from the Marshall Plan it lived through the "economic miracle" of the 1950s and brought in workers from Italy, Turkey and other countries. It joined NATO in 1955 and helped found the European Community. On 3 October 1990 it absorbed East Germany.', ev: ['coldwar', 'berlinwallfall'] },
  'st:Guyana': { txt: 'Guyana became independent from Britain in 1966, with Forbes Burnham in government, and became a republic in 1970. Its politics split between the descendants of Indians and those of Africans. From colonial times it inherited the dispute with Venezuela, which claims about two-thirds of its territory.' },
  'st:Suriname': { txt: 'Suriname became independent from the Netherlands on 25 November 1975, and many Surinamese emigrated to the former mother country. In 1980 a military coup brought Dési Bouterse to power, whose regime executed 15 opponents in December 1982. A war in the interior against Maroon groups lasted from 1986 to 1992.' },
  'st:Jamaica': { txt: 'Jamaica was a British colony from 1655 to 1962, one of the largest sugar producers in the world, with a long history of maroons (communities of escaped slaves) and of revolts, such as Sam Sharpe’s in 1831 and Morant Bay in 1865. It became independent on 6 August 1962. The island gave the world Marcus Garvey, one of the fathers of Pan-Africanism, and reggae.', ev: ['caribbean', 'abolition1807'] },
  'st:Trinidad and Tobago': { txt: 'Trinidad passed from Spain to Britain at the end of the 18th century, and Tobago changed hands several times before becoming British; the two islands were joined in 1889. After abolition many indentured workers came from India, and in the 20th century oil became the great source of wealth. The country became independent in 1962 under Eric Williams, a historian who showed how slavery financed British capitalism.', ev: ['caribbean'] },
  'st:Belize': { txt: 'Belize began as a camp of British cutters of logwood and mahogany, who worked with enslaved Africans from the 17th century on, on a coast claimed by Spain. It became the colony of British Honduras in 1862 and became independent on 21 September 1981. Guatemala claimed the territory for a long time.' },
  'st:Angola': { txt: 'The Portuguese founded Luanda in 1576, and for almost three centuries Angola was the largest source of enslaved Africans taken to Brazil. The war of independence began in 1961, and the country became independent on 11 November 1975, under the MPLA; Brazil was the first country to recognise it. A civil war soon began between the MPLA and UNITA, with Cuba, the Soviet Union, South Africa and the United States involved, and it ended only in 2002.', ev: ['luanda', 'slavetrade', 'luanda1641', 'coldwar'] },
  'st:Mozambique': { txt: 'The Portuguese presence in Mozambique began with Vasco da Gama in 1498, and for centuries it stayed almost entirely on the coast and in the Zambezi valley. FRELIMO fought for independence from 1964, won on 25 June 1975, with Samora Machel as president. A civil war against RENAMO, backed by Rhodesia and South Africa, lasted until 1992 and killed about 1 million people.', ev: ['gama', 'coldwar'] },

  /* eras.js: the world in 117 */
  'st:Rome': { txt: 'In AD 117, the year Trajan died, the Roman Empire was at its largest, from Britain to Mesopotamia, with perhaps 60 million inhabitants linked by roads, ports and a single currency. It governed cities with a great deal of local autonomy, sustained by taxes, a large frontier army and the labour of enslaved people.', ev: ['romanrepublic', 'fallofrome'] },
  'st:Parthia': { txt: 'The Parthian Empire, of the Arsacid dynasty, ruled Iran and Mesopotamia from about 247 BC to AD 224, with its capital at Ctesiphon. Its mounted archers defeated the Romans at Carrhae in 53 BC, and the empire acted as a middleman in the Silk Road trade between Rome and China. The Sasanians overthrew it in 224.', ev: ['hansilkroad'] },
  'st:Han': { txt: 'In AD 117 China was ruled by the Eastern Han, with its capital at Luoyang, an empire of about 50 million inhabitants recorded in the censuses. A few years earlier, in 105, a court official, Cai Lun, had presented paper to the emperor. The dynasty ended in 220.', ev: ['hansilkroad'] },
  'st:Kushan': { txt: 'The Kushan Empire, formed around the 1st century by a people from the steppes, the Yuezhi, stretched from Central Asia to northern India. Under King Kanishka, in the 2nd century, it protected Buddhism, which travelled from there to China, and the art of Gandhara blended Greek and Indian styles. It sat in the middle of the routes between Rome, Persia, India and China; it was dominated by the Sasanians in the 3rd century.', ev: ['hansilkroad'] },
  'st:Axum': { txt: 'Axum, in northern Ethiopia and Eritrea, controlled the Red Sea trade between the Roman Empire, Arabia and India through the port of Adulis. A Greek text from the 1st century already describes it as a kingdom rich in ivory. Its kings minted gold coins, and in the 4th century they adopted Christianity.' },

  /* eras.js: the world in 1279 */
  'st:Yuan': { txt: 'The Yuan dynasty was founded by Kublai Khan, grandson of Genghis, who ruled China from Dadu, today’s Beijing; in 1279 he completed the conquest of Song China in the south. The Yuan used paper money and had foreigners at court, such as, by his own account, the Venetian Marco Polo. Two invasions of Japan failed, in 1274 and 1281. A great revolt drove out the Mongols in 1368.', ev: ['mongols'] },
  'st:Golden Horde': { txt: 'The Golden Horde was the western Mongol khanate, created by Batu, grandson of Genghis Khan, with its capital at Sarai on the Volga River. For more than two centuries it collected tribute from the Russian principalities, including Moscow, and in the 14th century it converted to Islam. According to an account from the time, it was at the siege of Caffa, in Crimea, in 1346, that the Black Death passed to Genoese merchants. Weakened, the horde split apart in the 15th century.', ev: ['mongols', 'blackdeath'] },
  'st:Ilkhanate': { txt: 'The Ilkhanate was the Mongol khanate of Iran and Iraq, founded by Hulagu, grandson of Genghis Khan, who sacked Baghdad in 1258 and killed the caliph. In 1295 the khan Ghazan converted to Islam, and at his court the vizier Rashid al-Din wrote one of the first histories of the whole world. The khanate broke up after 1335.', ev: ['mongols', 'baghdad'] },
  'st:Chagatai': { txt: 'The Chagatai Khanate, founded by Genghis Khan’s second son, ruled Central Asia, between Turkestan and the steppes, through which the Silk Roads passed. It split into two parts in the 14th century, and from the western part came Tamerlane, who built his own empire from Samarkand.', ev: ['mongols'] },
  'st:Mamluks': { txt: 'The Mamluks were soldiers of slave origin who seized power in Egypt in 1250. In 1260 they defeated the Mongols at Ain Jalut and ruled Egypt and Syria until the Ottoman conquest of 1517, with Cairo as a great centre of trade and learning.', ev: ['mongols'] },
  'st:Delhi': { txt: 'The Delhi Sultanate, founded in 1206 by a former Turkish military slave, ruled much of northern India under five Muslim dynasties until 1526. It held off the Mongol invasions, built the Qutb Minar minaret and had one of the few women to rule in the medieval Islamic world, Sultana Razia (1236–1240). It was defeated by Babur, founder of the Mughal Empire, at Panipat.', ev: ['mongols'] },
  'st:Holy Roman Empire': { txt: 'The Holy Roman Empire brought together hundreds of principalities, free cities and Church territories in central Europe, under an emperor elected by princes. In 1273 Rudolf of Habsburg was elected, and his family would later hold the throne for centuries. Luther’s Reformation began inside the empire, and the Peace of Westphalia in 1648 gave the princes even more autonomy. Napoleon dissolved it in 1806.', ev: ['luther1517', 'westphalia', 'napoleon'] },
  'st:Byzantium': { txt: 'In 1279 the Byzantine Empire was much smaller than in the past: the crusaders had sacked Constantinople in 1204, and Emperor Michael VIII Palaiologos had retaken it only in 1261. It controlled parts of Greece and northwestern Anatolia and kept losing land to the Turks until the fall of the capital in 1453.', ev: ['constantinople1453'] },
  'st:Mali': { txt: 'In 1279 the Mali Empire, founded by Sundiata Keita around 1235, dominated the gold and salt trade of the western Sahel. In the following century, under Mansa Musa, it reached its height, and Timbuktu became a centre of Islamic learning.', ev: ['mansamusa'] },

  /* eras.js: the world in 1914 */
  'st:British': { txt: 'In 1914 the British Empire was the largest in history, with about a quarter of the world’s land and population: India, Canada, Australia, much of Africa, Caribbean islands and ports in Asia. It was also the financial centre of the world, and London lent to governments everywhere, including Brazil. After 1945 the empire broke up, starting with India in 1947.', ev: ['ww1', 'berlin1884', 'saltmarch', 'india1947'] },
  'st:Russian': { txt: 'In 1914 the Russian Empire, ruled by Tsar Nicholas II, stretched from Poland to the Pacific and brought together dozens of peoples, but it was largely agrarian and poor. Defeats in the First World War opened the way to the 1917 revolution, which overthrew the tsar and brought the Bolsheviks to power.', ev: ['ww1', 'russianrev1917'] },
  'st:French': { txt: 'In 1914 the French colonial empire was the second largest in the world, with Algeria, West and Equatorial Africa, Madagascar, Indochina and islands in the Caribbean and the Pacific. Hundreds of thousands of colonial soldiers fought for France in both world wars. The empire broke up after 1945, with wars in Indochina and Algeria and the independence of almost all the African colonies in 1960.', ev: ['berlin1884', 'ww1', 'decolonization1960'] },
  'st:Ottoman': { txt: 'By 1914 the Ottoman Empire had lost almost all of the Balkans and Libya, but still ruled Anatolia, Syria, Iraq and part of Arabia. It entered the First World War on Germany’s side and, in 1915, deported and massacred the Armenians, in a genocide that killed perhaps 1 million people. Defeated, it had its territory divided up, and the sultanate ended in 1922.', ev: ['ww1'] },
  'st:Japanese': { txt: 'By 1914 Japan already had a colonial empire: Taiwan, taken from China in 1895, Korea, annexed in 1910, and the south of Sakhalin island, taken from Russia in 1905. In the First World War it fought on the Allied side and took over the German possessions in China and the Pacific.', ev: ['meiji', 'ww1'] },
  'st:German': { txt: 'In 1914 the German Empire was the greatest industrial power in continental Europe and had colonies in Africa, such as today’s Namibia, Tanzania, Cameroon and Togo, and islands in the Pacific. It lost all of them in the Treaty of Versailles, after its defeat in the First World War.', ev: ['berlin1884', 'ww1'] },
  'st:Portuguese': { txt: 'In 1914 Portugal held Angola, Mozambique, Guinea, Cape Verde, São Tomé and Príncipe, Goa, Macau and Timor, where Africans were subjected to forced labour even after the end of slavery. Portugal fought in the First World War to protect its colonies, and kept them until the wars of independence and the Carnation Revolution of 1974–1975.', ev: ['berlin1884', 'ww1'] },
  'st:Austro-Hungarian': { txt: 'Austria-Hungary was a dual monarchy created in 1867 under Emperor Franz Joseph, bringing together Germans, Hungarians, Czechs, Poles, Croats, Serbs and other peoples. The assassination of the heir Franz Ferdinand by a Serbian nationalist in Sarajevo on 28 June 1914 led to the First World War. Defeated in 1918, the empire broke up into several countries.', ev: ['ww1'] },
  'st:Dutch': { txt: 'In 1914 the Netherlands held the Dutch East Indies, today’s Indonesia, one of the most profitable colonies in the world, as well as Suriname and the Antilles. They stayed neutral in the First World War. Indonesia became independent after a war, in 1949.', ev: ['vocamsterdam'] },
};

export const MONUMENTS = { ...LM, ...WP, ...CIV, ...ST };
